  {
    operation: "insert",
    dynamic: false,
    regex: new RegExp(
      String.raw`\bINSERT\s+INTO\s+${ENTITY_TARGET}(?:\s+AS\s+${STATIC_IDENTIFIER})?\s*(?:\(|\$\{|DEFAULT\b|OVERRIDING\b|VALUES\b|SELECT\b)`,
      "gi"
