1	/**
2	 * Generic state-machine guard for non-human entity updates. Entity types opt in
3	 * by storing `x-transitions` in `metadata_schema`; illegal moves are denied
4	 * rather than converted into approval requests.
5	 *
6	 * This applies only to update paths that call `runMutationGate`. Human edits,
7	 * create/delete, and merge/unmerge paths remain outside its scope. Frozen means
8	 * no value change: idempotently rewriting an existing value is allowed.
9	 */
10	
11	import { isDeepStrictEqual } from "node:util";
12	import type { DbClient } from "../db/client";
13	import type {
14		MutationInterceptor,
15		UpdateDecision,
16	} from "./entity-mutation-gate";
17	
18	/** One declared state and the moves that may leave it. */
19	interface TransitionState {
20		/** States this one may move to. Empty ⇒ terminal. */
21		to: string[];
22		/** When true, only the state field and `writableOnExit` fields may change. */
23		frozen: boolean;
24		/** Target state -> fields that may change alongside that transition. */
25		writableOnExit: Record<string, string[]>;
26	}
27	
28	interface TransitionSpec {
29		field: string;
30		states: Record<string, TransitionState>;
31	}
32	
33	/** Raised for a spec that is present but unusable; surfaces as a deny. */
34	class MalformedSpecError extends Error {}
35	
36	function asRecord(value: unknown): Record<string, unknown> | null {
37		return typeof value === "object" && value !== null && !Array.isArray(value)
38			? (value as Record<string, unknown>)
39			: null;
40	}
41	
42	function parseStringArray(value: unknown, where: string): string[] {
43		if (value === undefined) return [];
44		if (!Array.isArray(value) || value.some((v) => typeof v !== "string")) {
45			throw new MalformedSpecError(`${where} must be an array of strings`);
46		}
47		return value as string[];
