51	 * Parse a tenant-authored spec. Throws `MalformedSpecError` rather than
52	 * returning null: a type that declares `x-transitions` has opted in, so a
53	 * typo must fail loudly instead of silently disabling the invariant it asked
54	 * for. A type that declares nothing is untouched (see `loadSpec`).
55	 */
56	export function parseTransitionSpec(raw: unknown): TransitionSpec {
57		const spec = asRecord(raw);
58		if (!spec) throw new MalformedSpecError("x-transitions must be an object");
59	
60		const field = spec.field;
61		if (typeof field !== "string" || field.length === 0) {
62			throw new MalformedSpecError("x-transitions.field must be a non-empty string");
63		}
64	
65		const statesRaw = asRecord(spec.states);
66		if (!statesRaw || Object.keys(statesRaw).length === 0) {
67			throw new MalformedSpecError("x-transitions.states must be a non-empty object");
68		}
69	
70		const states = Object.create(null) as Record<string, TransitionState>;
71		for (const [name, value] of Object.entries(statesRaw)) {
72			const state = asRecord(value);
73			if (!state) {
74				throw new MalformedSpecError(`x-transitions.states.${name} must be an object`);
75			}
76			const frozen = state.frozen;
77			if (frozen !== undefined && typeof frozen !== "boolean") {
78				throw new MalformedSpecError(
79					`x-transitions.states.${name}.frozen must be a boolean`,
80				);
81			}
82			const writableOnExitRaw = asRecord(
83				state.writableOnExit === undefined ? {} : state.writableOnExit,
84			);
85			if (!writableOnExitRaw) {
86				throw new MalformedSpecError(
87					`x-transitions.states.${name}.writableOnExit must be an object`,
88				);
89			}
90			const writableOnExit = Object.create(null) as Record<string, string[]>;
91			for (const [target, fields] of Object.entries(writableOnExitRaw)) {
92				writableOnExit[target] = parseStringArray(
93					fields,
94					`x-transitions.states.${name}.writableOnExit.${target}`,
95				);
96			}
97			states[name] = {
98				to: parseStringArray(state.to, `x-transitions.states.${name}.to`),
99				frozen: frozen === true,
100				writableOnExit,
101			};
102		}
103	
104		// A `to` naming a state that does not exist can never be satisfied, so it is
105		// a typo rather than a rule. Catch it here instead of at the write.
106		for (const [name, state] of Object.entries(states)) {
107			for (const target of state.to) {
108				if (!Object.hasOwn(states, target)) {
109					throw new MalformedSpecError(
110						`x-transitions.states.${name}.to names unknown state "${target}"`,
111					);
112				}
113			}
114			for (const target of Object.keys(state.writableOnExit)) {
115				if (!state.to.includes(target)) {
116					throw new MalformedSpecError(
117						`x-transitions.states.${name}.writableOnExit names non-transition target "${target}"`,
118					);
119				}
120			}
121		}
122		return { field, states };
123	}
