import { beforeEach, describe, expect, it } from "vitest";
import type { Env } from "../../../index";
import type { ToolContext } from "../../../tools/registry";
import { createEntity, updateEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestAgent,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

const INVOICE_TRANSITIONS = {
	field: "status",
	states: {
		draft: { to: ["issued", "cancelled"] },
		issued: {
			to: ["posted", "cancelled"],
			frozen: true,
			writableOnExit: { posted: ["einvoice_uuid"] },
		},
		posted: { to: [], frozen: true },
		cancelled: { to: [], frozen: true },
	},
};

async function seedTypeWithTransitions(
	orgId: string,
	slug: string,
	transitions: unknown,
): Promise<void> {
	const sql = getTestDb();
	await sql`
	    INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
	                              created_at, updated_at)
	    VALUES (${orgId}, ${slug}, ${slug},
	            ${sql.json({ type: "object", "x-transitions": transitions })},
	            current_timestamp, current_timestamp)
	  `;
}

function agentToolContext(organizationId: string, agentId: string): ToolContext {
	return {
		organizationId,
		userId: null,
		memberRole: "owner",
		agentId,
		isAuthenticated: true,
		clientId: null,
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
		tokenType: "oauth",
		scopedToOrg: true,
		allowCrossOrg: false,
	} as unknown as ToolContext;
}

const TEST_ENV = {} as Env;

async function seedOrgAgentAndInvoice(status: string) {
	const org = await createTestOrganization({ name: "Entity Transitions" });
	const user = await createTestUser();
	await addUserToOrganization(user.id, org.id, "owner");
	const agent = await createTestAgent({ organizationId: org.id });
	await seedTypeWithTransitions(org.id, "invoice", INVOICE_TRANSITIONS);

	const invoice = await createEntity({
		entity_type: "invoice",
		name: `INV-${status}`,
		organization_id: org.id,
		created_by: user.id,
		metadata: { status, grand_total: 100 },
	} as Parameters<typeof createEntity>[0]);

	return { invoice, ctx: agentToolContext(org.id, agent.agentId) };
}

async function readMetadata(entityId: number): Promise<Record<string, unknown>> {
	const sql = getTestDb();
	const rows = await sql<{ metadata: unknown }[]>`
    SELECT metadata FROM entities WHERE id = ${entityId}
  `;
	const raw = rows[0].metadata;
	return (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
		string,
		unknown
	>;
}

describe("entity transitions (declarative state machine)", () => {
	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("denies an agent editing a frozen (posted) document", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("posted");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { grand_total: 999 } },
				TEST_ENV,
				ctx,
			),
		).rejects.toThrow(/frozen/i);

		const after = await readMetadata(invoice.id);
		expect(after.grand_total).toBe(100);
	});

	it("denies an illegal transition (draft -> posted)", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("draft");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { status: "posted" } },
				TEST_ENV,
				ctx,
			),
		).rejects.toThrow(/illegal transition/i);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("draft");
	});

	it("allows a legal transition (draft -> issued)", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("draft");

		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			ctx,
		);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("issued");
	});

	it("allows a field declared writableOnExit in the same write as the move", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("issued");

		// The companion value is known only when the transition happens.
		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "GIB-123" } },
			TEST_ENV,
			ctx,
		);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("posted");
		expect(after.einvoice_uuid).toBe("GIB-123");
	});

	it("denies a non-exempt field written alongside a legal move", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("issued");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { status: "posted", grand_total: 999 } },
				TEST_ENV,
				ctx,
			),
		).rejects.toThrow(/frozen/i);
	});

	it("allows an idempotent retry while frozen", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("posted");

		await updateEntity(
			invoice.id,
			{ metadata: { grand_total: 100 } },
			TEST_ENV,
			ctx,
		);

		const after = await readMetadata(invoice.id);
		expect(after.grand_total).toBe(100);
	});

	it("denies replacing the state with a non-string value", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("draft");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { status: null } },
				TEST_ENV,
				ctx,
			),
		).rejects.toThrow(/must be a string/i);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("draft");
	});

	it("denies renaming a frozen entity", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("posted");

		await expect(
			updateEntity(invoice.id, { name: "Renamed" }, TEST_ENV, ctx),
		).rejects.toThrow(/frozen/i);
	});

	it("denies slug and classifier changes on a frozen entity", async () => {
		const { invoice, ctx } = await seedOrgAgentAndInvoice("posted");

		await expect(
			updateEntity(
				invoice.id,
				{ slug: "renamed", enabled_classifiers: ["sentiment"] },
				TEST_ENV,
				ctx,
			),
		).rejects.toThrow(/cannot write \$enabled_classifiers, \$slug/);
	});

	it("ignores types that declare no x-transitions", async () => {
		const org = await createTestOrganization({ name: "No Transitions" });
		const user = await createTestUser();
		await addUserToOrganization(user.id, org.id, "owner");
		const agent = await createTestAgent({ organizationId: org.id });
		const sql = getTestDb();
		await sql`
      INSERT INTO entity_types (organization_id, slug, name, created_at, updated_at)
      VALUES (${org.id}, 'note', 'note', current_timestamp, current_timestamp)
    `;
		const note = await createEntity({
			entity_type: "note",
			name: "Free-form",
			organization_id: org.id,
			created_by: user.id,
			metadata: { status: "posted", body: "x" },
		} as Parameters<typeof createEntity>[0]);

		await updateEntity(
			note.id,
			{ metadata: { body: "y" } },
			TEST_ENV,
			agentToolContext(org.id, agent.agentId),
		);

		const after = await readMetadata(note.id);
		expect(after.body).toBe("y");
	});

	/**
	 * Deliberately NOT an ERP lifecycle. The engine in core must be
	 * domain-neutral, and the cheapest way to keep that true is to run the
	 * identical code path over a support-ticket lifecycle. If this case ever
	 * needs its own branch in `transition-interceptor.ts`, domain vocabulary has
	 * leaked into core.
	 */
	it("runs unchanged on a non-ERP domain (support ticket lifecycle)", async () => {
		const org = await createTestOrganization({ name: "Ticket Domain" });
		const user = await createTestUser();
		await addUserToOrganization(user.id, org.id, "owner");
		const agent = await createTestAgent({ organizationId: org.id });
		await seedTypeWithTransitions(org.id, "ticket", {
			field: "state",
			states: {
				open: { to: ["triaged"] },
				triaged: { to: ["closed"] },
				closed: { to: [], frozen: true },
			},
		});

		const ticket = await createEntity({
			entity_type: "ticket",
			name: "TKT-1",
			organization_id: org.id,
			created_by: user.id,
			metadata: { state: "closed", title: "boom" },
		} as Parameters<typeof createEntity>[0]);

		await expect(
			updateEntity(
				ticket.id,
				{ metadata: { title: "edited" } },
				TEST_ENV,
				agentToolContext(org.id, agent.agentId),
			),
		).rejects.toThrow(/frozen/i);
	});

	it("KNOWN GAP: a human edit is not gated, so it still mutates a frozen document", async () => {
		const org = await createTestOrganization({ name: "Human Gap" });
		const user = await createTestUser();
		await addUserToOrganization(user.id, org.id, "owner");
		await seedTypeWithTransitions(org.id, "invoice", INVOICE_TRANSITIONS);
		const invoice = await createEntity({
			entity_type: "invoice",
			name: "INV-human",
			organization_id: org.id,
			created_by: user.id,
			metadata: { status: "posted", grand_total: 100 },
		} as Parameters<typeof createEntity>[0]);

		const humanCtx = {
			organizationId: org.id,
			userId: user.id,
			memberRole: "owner",
			agentId: null,
			isAuthenticated: true,
			clientId: null,
			scopes: ["mcp:read", "mcp:write", "mcp:admin"],
			tokenType: "oauth",
			scopedToOrg: true,
			allowCrossOrg: false,
		} as unknown as ToolContext;

		await updateEntity(
			invoice.id,
			{ metadata: { grand_total: 999 } },
			TEST_ENV,
			humanCtx,
		);

		// `entity-management.ts` wraps the whole gate call in `if (!isHumanEdit)`,
		// so no interceptor sees a human write. This asserts TODAY'S behaviour on
		// purpose: closing the gap must be a deliberate flip of this expectation,
		// not something that silently starts passing.
		const after = await readMetadata(invoice.id);
		expect(after.grand_total).toBe(999);
	});
});

/**
 * Generic state-machine guard for non-human entity updates. Entity types opt in
 * by storing `x-transitions` in `metadata_schema`; illegal moves are denied
 * rather than converted into approval requests.
 *
 * This applies only to update paths that call `runMutationGate`. Human edits,
 * create/delete, and merge/unmerge paths remain outside its scope. Frozen means
 * no value change: idempotently rewriting an existing value is allowed.
 */

import { isDeepStrictEqual } from "node:util";
import type { DbClient } from "../db/client";
import type {
	MutationInterceptor,
	UpdateDecision,
} from "./entity-mutation-gate";

/** One declared state and the moves that may leave it. */
interface TransitionState {
	/** States this one may move to. Empty ⇒ terminal. */
	to: string[];
	/** When true, only the state field and `writableOnExit` fields may change. */
	frozen: boolean;
	/** Target state -> fields that may change alongside that transition. */
	writableOnExit: Record<string, string[]>;
}

interface TransitionSpec {
	field: string;
	states: Record<string, TransitionState>;
}

/** Raised for a spec that is present but unusable; surfaces as a deny. */
class MalformedSpecError extends Error {}

function asRecord(value: unknown): Record<string, unknown> | null {
	return typeof value === "object" && value !== null && !Array.isArray(value)
		? (value as Record<string, unknown>)
		: null;
}

function parseStringArray(value: unknown, where: string): string[] {
	if (value === undefined) return [];
	if (!Array.isArray(value) || value.some((v) => typeof v !== "string")) {
		throw new MalformedSpecError(`${where} must be an array of strings`);
	}
	return value as string[];
}

/**
 * Parse a tenant-authored spec. Throws `MalformedSpecError` rather than
 * returning null: a type that declares `x-transitions` has opted in, so a
 * typo must fail loudly instead of silently disabling the invariant it asked
 * for. A type that declares nothing is untouched (see `loadSpec`).
 */
export function parseTransitionSpec(raw: unknown): TransitionSpec {
	const spec = asRecord(raw);
	if (!spec) throw new MalformedSpecError("x-transitions must be an object");

	const field = spec.field;
	if (typeof field !== "string" || field.length === 0) {
		throw new MalformedSpecError("x-transitions.field must be a non-empty string");
	}

	const statesRaw = asRecord(spec.states);
	if (!statesRaw || Object.keys(statesRaw).length === 0) {
		throw new MalformedSpecError("x-transitions.states must be a non-empty object");
	}

	const states = Object.create(null) as Record<string, TransitionState>;
	for (const [name, value] of Object.entries(statesRaw)) {
		const state = asRecord(value);
		if (!state) {
			throw new MalformedSpecError(`x-transitions.states.${name} must be an object`);
		}
		const frozen = state.frozen;
		if (frozen !== undefined && typeof frozen !== "boolean") {
			throw new MalformedSpecError(
				`x-transitions.states.${name}.frozen must be a boolean`,
			);
		}
		const writableOnExitRaw = asRecord(
			state.writableOnExit === undefined ? {} : state.writableOnExit,
		);
		if (!writableOnExitRaw) {
			throw new MalformedSpecError(
				`x-transitions.states.${name}.writableOnExit must be an object`,
			);
		}
		const writableOnExit = Object.create(null) as Record<string, string[]>;
		for (const [target, fields] of Object.entries(writableOnExitRaw)) {
			writableOnExit[target] = parseStringArray(
				fields,
				`x-transitions.states.${name}.writableOnExit.${target}`,
			);
		}
		states[name] = {
			to: parseStringArray(state.to, `x-transitions.states.${name}.to`),
			frozen: frozen === true,
			writableOnExit,
		};
	}

	// A `to` naming a state that does not exist can never be satisfied, so it is
	// a typo rather than a rule. Catch it here instead of at the write.
	for (const [name, state] of Object.entries(states)) {
		for (const target of state.to) {
			if (!Object.hasOwn(states, target)) {
				throw new MalformedSpecError(
					`x-transitions.states.${name}.to names unknown state "${target}"`,
				);
			}
		}
		for (const target of Object.keys(state.writableOnExit)) {
			if (!state.to.includes(target)) {
				throw new MalformedSpecError(
					`x-transitions.states.${name}.writableOnExit names non-transition target "${target}"`,
				);
			}
		}
	}
	return { field, states };
}

/**
 * Read the spec off the entity's ACTUAL type row (joined through the entity, not
 * resolved by slug) so a type living in a public catalog org resolves the same
 * way the entity itself did. The caller has already locked the entity row in
 * the same transaction. Returns null when the type declares no `x-transitions`.
 */
async function loadSpec(
	sql: DbClient,
	entityId: number,
	organizationId: string,
): Promise<TransitionSpec | null> {
	const rows = await sql<{ metadata_schema: unknown }>`
    SELECT et.metadata_schema
    FROM entities e
    JOIN entity_types et ON et.id = e.entity_type_id
    WHERE e.id = ${entityId} AND e.organization_id = ${organizationId}
  `;
	if (rows.length === 0) return null;
	const rawSchema = rows[0].metadata_schema;
	const schema = asRecord(
		typeof rawSchema === "string" ? JSON.parse(rawSchema) : rawSchema,
	);
	const raw = schema?.["x-transitions"];
	if (raw === undefined) return null;
	return parseTransitionSpec(raw);
}

/**
 * Decide a single write against a parsed spec. Pure — exported so the rule
 * semantics are unit-testable without a database.
 *
 * Returns a deny reason, or null for "no opinion".
 */
export function evaluateTransition(args: {
	spec: TransitionSpec;
	current: Record<string, unknown>;
	proposed: Record<string, unknown>;
}): string | null {
	const { spec, current, proposed } = args;
	const fromRaw = current[spec.field];
	if (typeof fromRaw !== "string") return null;
	const from = Object.hasOwn(spec.states, fromRaw)
		? spec.states[fromRaw]
		: undefined;
	// An undeclared current state gets no opinion: a spec can only describe the
	// states it names, and failing closed here would freeze every row whose
	// value predates the rule. An undeclared target is still denied below,
	// because it can never appear in a declared `to` list.
	if (!from) return null;

	const proposesState = Object.hasOwn(proposed, spec.field);
	let movingTo: string | null = null;
	if (proposesState) {
		const proposedField = proposed[spec.field];
		if (typeof proposedField !== "string") {
			return `state field "${spec.field}" must be a string`;
		}
		if (proposedField !== fromRaw) movingTo = proposedField;
	}

	if (movingTo !== null && !from.to.includes(movingTo)) {
		return `illegal transition ${fromRaw} -> ${movingTo}`;
	}

	if (from.frozen) {
		const exempt = new Set<string>([spec.field]);
		if (movingTo !== null) {
			for (const f of from.writableOnExit[movingTo] ?? []) exempt.add(f);
		}
		const illegal = Object.keys(proposed).filter(
			(f) =>
				!exempt.has(f) &&
				!isDeepStrictEqual(current[f] ?? null, proposed[f] ?? null),
		);
		if (illegal.length > 0) {
			return `frozen in state "${fromRaw}": cannot write ${illegal.sort().join(", ")}`;
		}
	}
	return null;
}

/** Illegal updates override any field-approval requirements collected earlier. */
export const transitionInterceptor: MutationInterceptor = {
	name: "transitions",
	evaluate: async (req): Promise<UpdateDecision | null> => {
		if (req.action !== "update") return null;

		let spec: TransitionSpec | null;
		try {
			spec = await loadSpec(req.sql, req.entityId, req.organizationId);
		} catch (err) {
			if (err instanceof MalformedSpecError) {
				return { outcome: "deny", reason: `invalid x-transitions: ${err.message}` };
			}
			throw err;
		}
		if (!spec) return null;

		const reason = evaluateTransition({
			spec,
			current: req.current,
			proposed: req.proposed,
		});
		return reason === null ? null : { outcome: "deny", reason };
	},
};

import { describe, expect, it } from "vitest";
import type { DbClient } from "../../db/client";
import {
	evaluateTransition,
	parseTransitionSpec,
	transitionInterceptor,
} from "../transition-interceptor";

const INVOICE = parseTransitionSpec({
	field: "status",
	states: {
		draft: { to: ["issued", "cancelled"] },
		issued: {
			to: ["posted", "cancelled"],
			frozen: true,
			writableOnExit: { posted: ["einvoice_uuid"] },
		},
		posted: { to: [], frozen: true },
		cancelled: { to: [], frozen: true },
	},
});

function decide(
	current: Record<string, unknown>,
	proposed: Record<string, unknown>,
): string | null {
	return evaluateTransition({ spec: INVOICE, current, proposed });
}

describe("parseTransitionSpec", () => {
	it("accepts a minimal spec and defaults frozen/writableOnExit", () => {
		const spec = parseTransitionSpec({
			field: "state",
			states: { open: { to: [] } },
		});
		expect(spec.field).toBe("state");
		expect(spec.states.open.frozen).toBe(false);
		expect(spec.states.open.writableOnExit).toEqual({});
	});

	it.each([
		["a non-object", "nope"],
		["a missing field", { states: { a: { to: [] } } }],
		["an empty field", { field: "", states: { a: { to: [] } } }],
		["missing states", { field: "s" }],
		["empty states", { field: "s", states: {} }],
		["a non-object state", { field: "s", states: { a: 1 } }],
		["a non-boolean frozen", { field: "s", states: { a: { to: [], frozen: "y" } } }],
		["a non-array to", { field: "s", states: { a: { to: "b" } } }],
		["a non-string in to", { field: "s", states: { a: { to: [2] } } }],
		[
			"a non-object writableOnExit",
			{ field: "s", states: { a: { to: [], writableOnExit: [] } } },
		],
		[
			"a null writableOnExit",
			{ field: "s", states: { a: { to: [], writableOnExit: null } } },
		],
		[
			"a non-string writableOnExit field",
			{
				field: "s",
				states: { a: { to: ["b"], writableOnExit: { b: [2] } }, b: { to: [] } },
			},
		],
	])("rejects %s", (_label, raw) => {
		expect(() => parseTransitionSpec(raw)).toThrow();
	});

	it("rejects a `to` naming a state that does not exist", () => {
		expect(() =>
			parseTransitionSpec({ field: "s", states: { a: { to: ["ghost"] } } }),
		).toThrow(/unknown state "ghost"/);
	});

	it("rejects writableOnExit for a target that is not an outbound transition", () => {
		expect(() =>
			parseTransitionSpec({
				field: "s",
				states: {
					a: { to: ["b"], writableOnExit: { c: ["receipt"] } },
					b: { to: [] },
					c: { to: [] },
				},
			}),
		).toThrow(/non-transition target "c"/);
	});
});

describe("evaluateTransition", () => {
	it("allows a declared move", () => {
		expect(decide({ status: "draft" }, { status: "issued" })).toBeNull();
	});

	it("denies an undeclared move", () => {
		expect(decide({ status: "draft" }, { status: "posted" })).toMatch(
			/illegal transition draft -> posted/,
		);
	});

	it("denies any move out of a terminal state", () => {
		expect(decide({ status: "posted" }, { status: "draft" })).toMatch(
			/illegal transition/,
		);
	});

	it("denies editing a non-state field while frozen", () => {
		expect(decide({ status: "posted" }, { grand_total: 1 })).toMatch(
			/frozen in state "posted".*grand_total/,
		);
	});

	it("names every offending field, sorted, so the error is deterministic", () => {
		const reason = decide({ status: "posted" }, { b: 1, a: 2 });
		expect(reason).toMatch(/cannot write a, b$/);
	});

	it("allows a writableOnExit field in the same write as its move", () => {
		expect(
			decide({ status: "issued" }, { status: "posted", einvoice_uuid: "x" }),
		).toBeNull();
	});

	it("scopes writableOnExit to the declared target, not any move", () => {
		// einvoice_uuid is writable on issued->posted only; issued->cancelled is a
		// legal move but must not carry it.
		expect(
			decide({ status: "issued" }, { status: "cancelled", einvoice_uuid: "x" }),
		).toMatch(/frozen in state "issued".*einvoice_uuid/);
	});

	it("does not grant writableOnExit when the state field is absent", () => {
		expect(decide({ status: "issued" }, { einvoice_uuid: "x" })).toMatch(
			/frozen in state "issued"/,
		);
	});

	it("allows a no-op rewrite of the state field while frozen", () => {
		expect(decide({ status: "posted" }, { status: "posted" })).toBeNull();
	});

	it("allows no-op retries of other fields while frozen", () => {
		expect(
			decide(
				{ status: "posted", totals: { net: 100, tax: 20 } },
				{ totals: { tax: 20, net: 100 } },
			),
		).toBeNull();
	});

	it.each([null, 7, undefined])(
		"denies replacing a declared state with non-string %s",
		(value) => {
			expect(decide({ status: "draft" }, { status: value })).toMatch(
				/state field "status" must be a string/,
			);
		},
	);

	it("covers reserved $-attributes, so a frozen entity cannot be renamed", () => {
		expect(decide({ status: "posted" }, { $name: "new" })).toMatch(
			/frozen in state "posted".*\$name/,
		);
	});

	it("abstains when the current state is not declared", () => {
		// Adoption: a spec added to a type with existing rows must not freeze every
		// row whose value predates it.
		expect(decide({ status: "legacy" }, { grand_total: 1 })).toBeNull();
	});

	it("abstains when the state field is absent or non-string", () => {
		expect(decide({}, { grand_total: 1 })).toBeNull();
		expect(decide({ status: 7 }, { grand_total: 1 })).toBeNull();
	});

	it("allows unrestricted edits in a non-frozen declared state", () => {
		expect(decide({ status: "draft" }, { grand_total: 1 })).toBeNull();
	});
});

describe("transitionInterceptor", () => {
	it.each([
		[
			"an invalid shape",
			{ field: "status", states: "invalid" },
			"x-transitions.states must be a non-empty object",
		],
		["null", null, "x-transitions must be an object"],
	])("fails closed when a type declares %s", async (_label, raw, reason) => {
		const sql = (() =>
			Promise.resolve([
				{ metadata_schema: { "x-transitions": raw } },
			])) as unknown as DbClient;
		const decision = await transitionInterceptor.evaluate({
			action: "update",
			organizationId: "org-1",
			principalKind: "agent",
			sql,
			attribution: "agent",
			entityTypeSlug: "invoice",
			entityId: 1,
			fields: { status: "none" },
			current: { status: "draft" },
			proposed: { status: "issued" },
		});

		expect(decision).toEqual({
			outcome: "deny",
			reason: `invalid x-transitions: ${reason}`,
		});
	});
});

