commit 4f06e9ee398ab764bcf9f969257f37ebb2a51433
Author: Burak Emre Kabakcı <emrekabakci@gmail.com>
Date:   Mon Aug 17 05:28:27 2026 +0100

    feat(server): enforce declarative entity state transitions

    Adds a generic state-machine interceptor to the entity mutation gate. Types
    opt in by declaring x-transitions on metadata_schema; the engine knows only
    field/states/to/frozen/writableOnExit and no domain vocabulary.

    The update gate was value-blind: it received field ownership but neither the
    current nor the proposed values, so it could not express a data-dependent rule.
    UpdateMutationRequest now carries both, read under the row lock the caller
    already holds. Making them required surfaced a second construction site in
    promote-keyed-entities, which had no locked read before the gate.

    No public surface change: no migration, and x-transitions rides the existing
    free-form metadataSchema and schemaExtras passthrough. Inert until a type
    declares a spec.

diff --git a/packages/server/src/authz/entity-mutation-gate.ts b/packages/server/src/authz/entity-mutation-gate.ts
index 0f332fa69..0ff8b1926 100644
--- a/packages/server/src/authz/entity-mutation-gate.ts
+++ b/packages/server/src/authz/entity-mutation-gate.ts
@@ -47,6 +47,7 @@ import {
 	buildCreateDeferral,
 	buildFieldChangeDeferral,
 } from "./approval-interceptor";
+import { transitionInterceptor } from "./transition-interceptor";

 export type MutationPrincipalKind = "user" | "agent" | "automation";

@@ -123,6 +124,16 @@ export interface UpdateMutationRequest extends EntityMutationBase {
 	entityOrgId?: string | null;
 	/** field path (incl. reserved $-attributes) -> current owner. */
 	fields: Record<string, FieldOwner>;
+	/**
+	 * Current metadata plus reserved `$`-attributes a data-dependent interceptor
+	 * may inspect, read under the same row lock as the eventual write.
+	 */
+	current: Record<string, unknown>;
+	/**
+	 * Proposed metadata and reserved `$`-attribute values before the ownership
+	 * merge. `fields` is the subset understood by ownership and approval policy.
+	 */
+	proposed: Record<string, unknown>;
 }

 export type EntityMutationRequest =
@@ -178,6 +189,7 @@ export interface MutationInterceptor {
  */
 const BUILTIN_INTERCEPTORS: readonly MutationInterceptor[] = [
 	approvalInterceptor,
+	transitionInterceptor,
 ];

 const registry: MutationInterceptor[] = [...BUILTIN_INTERCEPTORS];

