1	/**
2	 * Running an Automation's eval suite and reading the answer (evals PR 4, lobu#2564).
3	 *
4	 * Scoring one replay produces a number. This module is what makes that number
5	 * mean something: it replays every active case of an Automation N times, and reads
6	 * back per-case latest-vs-previous so the question people actually have — "I
7	 * edited this Automation, did I break it?" — has an answer.
8	 *
9	 * **Trials are not optional decoration.** Our own research evals swung ±1 task
10	 * on identical 22-task batteries. A single run per case reports noise as a
11	 * regression, so `readEvalResults` compares the MEAN of the latest trial group
12	 * against the mean of the previous one and reports the spread it saw. A delta
13	 * smaller than the observed spread is not a signal, and the payload says so
14	 * rather than leaving the reader to infer it.
15	 *
16	 * **Nothing here aggregates history.** Results come from the case ENTITIES'
17	 * rolling `recent_scores` window (bounded at CASE_SCORE_WINDOW, written by the
18	 * scorer). `entities` is a config-sized table the invariants permit reading at
19	 * request time; `events` is not, and is never touched on this path.
20	 */
21	
22	import { unvalidatedEntityRowPatch } from "../authz/entity-row-validation";
23	import { type DbClient, getDb } from "../db/client.js";
24	import { EVAL_CASE_ENTITY_TYPE_SLUG } from "../tools/constants.js";
25	import {
26		patchEntityRows,
27		withEntityWriteTransaction,
28	} from "../utils/entity-management.js";
29	import logger from "../utils/logger.js";
30	import { trialCaseKey } from "./eval-cases.js";
31	import { createEvalRun } from "./eval-runs.js";
32	import type { CaseScoreEntry } from "./eval-scores.js";
33	
34	/**
35	 * Trials per case in one suite run. More is better statistics and linearly more
36	 * provider spend, so the default is the smallest number that can show a spread
37	 * at all; a caller who wants tighter bounds asks for more.
38	 */
39	const DEFAULT_TRIALS = 3;
40	
41	/**
42	 * Ceiling per request, so one call cannot queue an unbounded replay burst.
43	 *
44	 * Bounded by `CASE_SCORE_WINDOW` (eval-scores.ts) as much as by spend: results
45	 * compare the latest `trials` scores against the previous `trials`, so raising
46	 * this past half the window would leave the baseline group unreadable.
47	 */
48	const MAX_TRIALS = 10;
49	
50	interface EvalSuiteCase {
51		caseId: number;
52		name: string;
53		caseKey: string;
54		sourceRunId: number;
55	}
56	
57	export interface RunEvalSuiteResult {
58		automationId: number;
59		trials: number;
60		/** Runs actually queued. Fewer than cases×trials when a replay is in flight. */
61		queued: number;
62		cases: Array<{ caseId: number; runIds: number[] }>;
63		/** Cases that could not be replayed at all, with the reason. */
64		skipped: Array<{ caseId: number; reason: string }>;
65	}
66	
67	/**
68	 * Load an Automation's ACTIVE eval cases.
69	 *
70	 * Retired cases are excluded here rather than at the call site: a retired case
71	 * is one a human decided no longer describes desired semantics, and silently
72	 * continuing to run it would make the suite report failures nobody wants fixed.
73	 */
74	async function listActiveCases(
75		organizationId: string,
76		automationId: number,
77		caseIds?: number[],
78		db?: DbClient,
79	): Promise<EvalSuiteCase[]> {
80		const sql = db ?? getDb();
81		const filterIds = caseIds?.filter((n) => Number.isSafeInteger(n) && n > 0);
82		// Asked for a subset and named nothing usable → nothing. Falling through to
83		// the unfiltered query would silently replay every case instead.
84		if (caseIds?.length && !filterIds?.length) return [];
85		const rows = (await sql`
86	    SELECT e.id, e.name, e.metadata
87	    FROM entities e
88	    JOIN entity_types et ON et.id = e.entity_type_id
89	    WHERE e.organization_id = ${organizationId}
90	      AND et.slug = ${EVAL_CASE_ENTITY_TYPE_SLUG}
91	      AND e.deleted_at IS NULL
92	      AND (e.metadata->>'automation_id')::bigint = ${automationId}
93	      AND coalesce(e.metadata->>'status', 'active') = 'active'
94	      ${
95					// The client runs with `fetch_types: false`, so a raw JS array binds as
96					// "malformed array literal". Format the `{n,n}` literal and cast it,
97					// exactly like insert-event.ts does for entity_ids. It is still a bound
98					// parameter rather than interpolated SQL — but it binds as TEXT, so a
99					// non-integer would arrive as `NaN` and fail the cast at runtime.
100					// Hence the filter above, rather than a promise about callers.
101					filterIds?.length
102						? sql`AND e.id = ANY(${`{${filterIds.join(",")}}`}::bigint[])`
103						: sql``
104				}
105	    ORDER BY e.id
106	  `) as unknown as Array<{
107			id: number | string;
108			name: string;
109			metadata: Record<string, unknown> | null;
110		}>;
111	
112		const cases: EvalSuiteCase[] = [];
113		for (const row of rows) {
114			const metadata = row.metadata ?? {};
115			const sourceRunId = Number(metadata.source_run_id);
116			if (!Number.isSafeInteger(sourceRunId) || sourceRunId < 1) continue;
117			cases.push({
118				caseId: Number(row.id),
119				name: row.name,
120				caseKey:
121					typeof metadata.case_key === "string" ? metadata.case_key : "default",
122				sourceRunId,
123			});
124		}
125		return cases;
126	}
127	
128	/** Stamp the queued trial group without clobbering a concurrent score update. */
129	async function stampSuiteTrials(
130		db: DbClient,
131		organizationId: string,
132		caseEntityId: number,
133		trials: number,
134	): Promise<void> {
135		await withEntityWriteTransaction(db, async (tx) => {
136			const rows = await tx<{ metadata: Record<string, unknown> | null }>`
137	      SELECT metadata
138	      FROM entities
139	      WHERE id = ${caseEntityId}
140	        AND organization_id = ${organizationId}
141	        AND deleted_at IS NULL
142	      FOR UPDATE
143	    `;
144			if (rows.length === 0) return;
145			await patchEntityRows({
146				tx,
147				ids: [caseEntityId],
148				patch: unvalidatedEntityRowPatch({
149					patch: {
150						metadata: { ...(rows[0].metadata ?? {}), suite_trials: trials },
151					},
152					reason: 'eval scaffolding bookkeeping on platform-owned eval entities',
153				}),
154			});
155		});
156	}
157	
158	/**
159	 * Replay every active case `trials` times.
160	 *
161	 * Each trial gets its own key via `trialCaseKey`, because `createEvalRun`
162	 * dedups on (sourceRunId, caseKey) — without distinct keys five trials would
163	 * collapse into one run and report a single measurement as five.
164	 *
165	 * A case whose source run is no longer replayable is SKIPPED with a reason
166	 * rather than failing the whole suite: one un-replayable case must not stop the
167	 * other twenty from being measured, and a silent omission would make the suite
168	 * look healthier than it is.
169	 */
170	export async function runEvalSuite(
171		params: {
172			organizationId: string;
173			automationId: number;
174			caseIds?: number[];
175			trials?: number;
176		},
177		db?: DbClient,
178	): Promise<RunEvalSuiteResult> {
179		const sql = db ?? getDb();
180		const trials = Math.min(
181			MAX_TRIALS,
182			Math.max(1, Math.trunc(params.trials ?? DEFAULT_TRIALS)),
183		);
184	
185		const cases = await listActiveCases(
186			params.organizationId,
187			params.automationId,
188			params.caseIds,
189			sql,
190		);
191	
192		const result: RunEvalSuiteResult = {
193			automationId: params.automationId,
194			trials,
195			queued: 0,
196			cases: [],
197			skipped: [],
198		};
199	
200		for (const evalCase of cases) {
201			const runIds: number[] = [];
202			for (let trial = 0; trial < trials; trial += 1) {
203				const minted = await createEvalRun(
204					{
205						sourceRunId: evalCase.sourceRunId,
206						caseKey: trialCaseKey(evalCase.caseKey, trial),
207					},
