2	 * Tool: manage_view_templates
3	 *
4	 * Unified view template versioning for entity types and individual entities.
5	 * Actions: set, get, rollback, remove_tab
6	 */
7	
8	
9	import { validateEntityRowPatch } from "../../authz/entity-row-validation";
10	import {
11	  ManageViewTemplatesResultSchema,
12	  ManageViewTemplatesSchema,
13	  type ManageViewTemplatesArgs,
14	  type ManageViewTemplatesResult,
15	  type ViewTemplateVersionRow,
16	} from '@lobu/core/contracts/tools/manage-view-templates';
17	import { type DbClient, getDb } from '../../db/client';
18	import { emit } from '../../events/emitter';
19	import { recordToolConfigChange } from './helpers/config-audit';
20	import { ToolUserError } from '../../utils/errors';
21	import { patchEntityRows } from '../../utils/entity-management';
22	import { validateDataSourceQuery } from '../../utils/execute-data-sources';
