31	// ============================================
32	// View template versioning helpers
33	// ============================================
34	
35	function mapVersionRow(row: Record<string, unknown>): ViewTemplateVersionRow {
36	  return {
37	    id: Number(row.id),
38	    version: Number(row.version),
39	    tab_name: row.tab_name ? String(row.tab_name) : null,
40	    tab_order: Number(row.tab_order) || 0,
41	    json_template: row.json_template as Record<string, unknown>,
42	    change_notes: row.change_notes ? String(row.change_notes) : null,
43	    created_by: String(row.created_by),
44	    created_by_username: row.created_by_username ? String(row.created_by_username) : null,
45	    created_at: String(row.created_at),
46	  };
47	}
48	
49	// ============================================
50	// Main Function
51	// ============================================
52	
53	export const manageViewTemplates = withValidatedArgs(
54	  'manage_view_templates',
55	  ManageViewTemplatesSchema,
56	  defineFlatActionTool<ManageViewTemplatesArgs, ManageViewTemplatesResult>(
57	    'manage_view_templates',
58	    {
59	      set: flatAction(handleSet),
60	      get: flatAction(handleGet),
61	      rollback: flatAction(handleRollback),
62	      remove_tab: flatAction(handleRemoveTab),
63	      clear: flatAction(handleClear),
64	    }
65	  )
66	);
67	
68	// ============================================
69	// Helpers
70	// ============================================
71	
72	/** Column on the parent table that holds the default tab FK */
73	function parentTable(resourceType: string): string {
74	  if (resourceType === 'entity_type') return 'entity_types';
75	  if (resourceType === 'entity') return 'entities';
76	  throw new Error(`Unknown resource type: ${resourceType}`);
77	}
78	
79	/** Resolve resource_id to a consistent string for view_template_versions.resource_id */
80	function rid(args: ManageViewTemplatesArgs): string {
81	  return String(args.resource_id);
82	}
83	
84	/**
85	 * Point a verified resource at a default template version while rechecking the
86	 * mutable parent under the caller's transaction — `verifyAccess` ran outside
87	 * it. An entity row is rechecked (and pinned) by a `FOR UPDATE` select before
88	 * the physical write kernel patches it; an entity type, a configuration row on
89	 * a separate statically selected table, is rechecked by its own UPDATE.
90	 */
91	async function setCurrentDefaultVersion(
92	  tx: DbClient,
93	  args: ManageViewTemplatesArgs,
94	  ctx: ToolContext,
95	  rowId: number,
96	  versionId: number | null
97	): Promise<void> {
98	  if (args.resource_type === 'entity') {
99	    const locked = await tx<{ id: number }>`
100	      SELECT id
101	      FROM entities
102	      WHERE id = ${rowId}
103	        AND organization_id = ${ctx.organizationId}
104	        AND deleted_at IS NULL
105	      FOR UPDATE
106	    `;
107	    if (locked.length === 0) {
108	      throw new ToolUserError(`Entity ${rid(args)} not found`, 404);
109	    }
110	    await patchEntityRows({
111	      tx,
112	      ids: [rowId],
113	      patch: await validateEntityRowPatch({
114	        tx,
115	        ids: [rowId],
116	        patch: { currentViewTemplateVersionId: versionId },
117	      }),
118	    });
119	    return;
120	  }
121	
122	  const changed = await tx<{ id: number }>`
123	    UPDATE entity_types
124	    SET current_view_template_version_id = ${versionId}, updated_at = NOW()
125	    WHERE id = ${rowId}
126	      AND organization_id = ${ctx.organizationId}
127	      AND deleted_at IS NULL
128	    RETURNING id
129	  `;
130	  if (changed.length !== 1) {
131	    throw new ToolUserError(`Entity type '${rid(args)}' not found`, 404);
132	  }
133	}
134	
135	/**
136	 * Config-audit emission for view-template mutations. Only entity-type
137	 * templates are org config (the audit trail has no 'entity' resource kind —
138	 * per-entity templates are runtime data), so entity-scoped mutations are
139	 * skipped. The audit kind stays 'entity-type' with changedFields
140	 * ['view_template'] per the ConfigResourceKind union.
141	 */
142	function recordViewTemplateChange(
143	  args: ManageViewTemplatesArgs,
144	  ctx: ToolContext,
145	  summary: string,
146	  state: Record<string, unknown> | null
147	): void {
148	  if (args.resource_type !== 'entity_type') return;
149	  recordToolConfigChange(ctx, {
150	    resourceKind: 'entity-type',
151	    resourceId: rid(args),
152	    op: 'updated',
153	    summary,
154	    state,
155	    changedFields: ['view_template'],
156	  });
157	}
158	
159	/** Verify the resource exists and the caller has access. Returns the numeric row id. */
160	async function verifyAccess(
161	  sql: ReturnType<typeof getDb>,
162	  args: ManageViewTemplatesArgs,
163	  ctx: ToolContext,
164	  requireWrite: boolean
165	): Promise<number> {
166	  if (requireWrite && !ctx.userId) throw new Error('Authentication required');
167	
168	  const rt = args.resource_type;
169	
170	  // Boundary validation (`withValidatedArgs`) guarantees resource_type and
171	  // resource_id are present and well-typed, but a whitespace-only string
172	  // still satisfies the schema and would query for a blank slug.
173	  if (String(args.resource_id).trim() === '') {
174	    throw new ToolUserError(`resource_id is required (got ${JSON.stringify(args.resource_id)})`);
175	  }
176	
177	  const id = rid(args);
178	
179	  if (rt === 'entity_type') {
180	    const rows = await sql`
181	      SELECT id, organization_id, created_by FROM entity_types
182	      WHERE slug = ${id} AND deleted_at IS NULL
183	        AND (organization_id = ${ctx.organizationId} OR organization_id IS NULL)
184	      LIMIT 1
185	    `;
