27	function cosineSimilarity(a: number[], b: number[]): number {
28		let dot = 0;
29		let normA = 0;
30		let normB = 0;
31		for (let i = 0; i < a.length; i++) {
32			dot += a[i] * b[i];
33			normA += a[i] * a[i];
34			normB += b[i] * b[i];
35		}
36		const denom = Math.sqrt(normA) * Math.sqrt(normB);
37		if (denom === 0) return 0;
38		return dot / denom;
