153	 * Supports: $.field, $.field[*], $.field[*].subfield
154	 *
155	 * @example
156	 * extractAtPath(data, "$.problems_analysis.top_problems[*]")
157	 * // Returns array of all items in top_problems
158	 */
159	function extractAtPath(data: any, path: string): any[] {
160		if (!data || !path) {
161			return [];
162		}
163	
164		// Remove leading $. if present
165		const cleanPath = path.startsWith("$.") ? path.slice(2) : path;
166	
167		// Split by [*] to handle array traversal
168		const segments = cleanPath.split("[*]");
169	
170		function traverse(obj: any, segmentIndex: number): any[] {
171			if (segmentIndex >= segments.length) {
172				return [obj];
173			}
174	
175			const segment = segments[segmentIndex]
176				.replace(/^\./, "")
177				.replace(/\.$/, "");
178	
