=== guardrail types: stages + signature ===
/**
 * Guardrail primitive — composable input/output/pre-tool checks that can halt
 * a run before it produces user-visible output or side effects. Modeled on
 * OpenAI Agents SDK's input_guardrails / output_guardrails pattern.
 *
 * A guardrail returns `{ tripped: true, reason, metadata }` to halt; the
 * runner cancels the remaining guardrails at the same stage on first trip.
 *
 * Guardrails are stage-scoped:
 *   - `input`    — user message before dispatch to worker
 *   - `output`   — worker-produced text/attachments before user rendering
 *   - `pre-tool` — tool call authorization (agent → gateway MCP proxy)
 *   - `egress`   — outbound network request authorization, evaluated in the
 *                  http-proxy egress plane (LLM egress judge). Enforcement
 *                  stays in the proxy — this stage is NOT run by the message
 *                  pipeline; it exists so egress denials share the guardrail
 *                  stage taxonomy and audit trail (`guardrail-trip` events).
 *
 * Register guardrails in a {@link GuardrailRegistry} and enable them per-agent
 * via `defineAgent({ guardrails: ["name-a", "name-b"] })` in `lobu.config.ts`.
 */

export type GuardrailStage = "input" | "output" | "pre-tool" | "egress";

/**
 * Context shape passed to each stage. Each stage has a distinct payload so
 * guardrails can be typed against what they'll actually inspect. Additional
 * fields can be added over time — guardrails should read only what they need.
 */
export interface InputGuardrailContext {
  agentId: string;
  userId: string;
  message: string;
  platform: string;
  conversationId?: string;
}

export interface OutputGuardrailContext {
  agentId: string;
  userId: string;
  /** Full response text or streamed delta being inspected. */
  text: string;
  platform: string;
  conversationId?: string;
  /**
   * Tool names the worker recorded for this turn (from `tool_execution_end`).
   * Present on terminal completion rows from workers that stamp `toolsUsed`
   * (including `[]` when no tools ran). Absent on older workers and synthetic
   * gateway terminals; require-tool treats absence as unknown/pass.
   */
  toolsUsed?: string[];
}

export interface PreToolGuardrailContext {
  agentId: string;
  userId: string;
  toolName: string;
  /** Raw JSON-RPC params the worker is about to invoke the tool with. */
  arguments: unknown;
  conversationId?: string;
}

/**
 * Context for an egress decision. Unlike the other stages this is NOT
 * evaluated in the message pipeline — it is produced by the http-proxy egress
 * plane (the LLM egress judge) which owns enforcement. The stage exists so
 * egress denials are typed against the same taxonomy and emit the same
 * `guardrail-trip` audit events as message-pipeline guardrails.
 */
export interface EgressGuardrailContext {

