1	/**
2	 * Declarative state-machine rules for entity rows — the VALIDATION half of
3	 * entity write policy, deliberately separate from the permission half.
4	 *
5	 * `runMutationGate` answers a PERMISSION question: may this principal write
6	 * this field. Its request is keyed on `principalKind`, ownership, and approval
7	 * state. This module answers a VALIDATION question: is the resulting state
8	 * legal. That question has no principal in it — a posted invoice is immutable
9	 * whether an agent, an automation, or a human proposed the write — which is
10	 * exactly why these rules must not live in a principal-keyed pipeline.
11	 *
12	 * Pure: no database, no clock, no principal. Entity types opt in by storing
13	 * `x-transitions` on `entity_types.metadata_schema`; a type declaring nothing
14	 * is untouched. "Frozen" means no VALUE change, so an idempotent rewrite of an
15	 * existing value is allowed.
16	 */
17	
18	import { isDeepStrictEqual } from "node:util";
19	
20	/** One declared state and the moves that may leave it. */
21	interface TransitionState {
22		/** States this one may move to. Empty ⇒ terminal. */
23		to: string[];
24		/** When true, only the state field and `writableOnExit` fields may change. */
25		frozen: boolean;
26		/** Target state -> fields that may change alongside that transition. */
27		writableOnExit: Record<string, string[]>;
28	}
29	
30	export interface TransitionSpec {
31		field: string;
32		states: Record<string, TransitionState>;
33	}
34	
35	/** Raised for a spec that is present but unusable; the caller fails closed. */
36	export class MalformedSpecError extends Error {}
37	
38	function asRecord(value: unknown): Record<string, unknown> | null {
39		return typeof value === "object" && value !== null && !Array.isArray(value)
40			? (value as Record<string, unknown>)
41			: null;
42	}
43	
44	function parseStringArray(value: unknown, where: string): string[] {
45		if (value === undefined) return [];
46		if (!Array.isArray(value) || value.some((v) => typeof v !== "string")) {
47			throw new MalformedSpecError(`${where} must be an array of strings`);
48		}
49		return value as string[];
50	}
51	
52	/**
53	 * Parse a tenant-authored spec. Throws rather than returning null: a type that
54	 * declares `x-transitions` has opted in, so a typo must fail loudly instead of
55	 * silently disabling the invariant it asked for.
56	 *
57	 * State names are tenant data used as object keys, so every map here is a
58	 * null-prototype object and every membership test uses `Object.hasOwn` — a
59	 * state named `constructor` must not resolve through the prototype chain.
60	 */
61	export function parseTransitionSpec(raw: unknown): TransitionSpec {
62		const spec = asRecord(raw);
63		if (!spec) throw new MalformedSpecError("x-transitions must be an object");
64	
65		const field = spec.field;
66		if (typeof field !== "string" || field.length === 0) {
67			throw new MalformedSpecError(
68				"x-transitions.field must be a non-empty string",
69			);
70		}
71	
72		const statesRaw = asRecord(spec.states);
73		if (!statesRaw || Object.keys(statesRaw).length === 0) {
74			throw new MalformedSpecError(
75				"x-transitions.states must be a non-empty object",
76			);
77		}
78	
79		const states = Object.create(null) as Record<string, TransitionState>;
80		for (const [name, value] of Object.entries(statesRaw)) {
81			const state = asRecord(value);
82			if (!state) {
83				throw new MalformedSpecError(
84					`x-transitions.states.${name} must be an object`,
85				);
86			}
87			const frozen = state.frozen;
88			if (frozen !== undefined && typeof frozen !== "boolean") {
89				throw new MalformedSpecError(
90					`x-transitions.states.${name}.frozen must be a boolean`,
91				);
92			}
93			const writableOnExitRaw = asRecord(
94				state.writableOnExit === undefined ? {} : state.writableOnExit,
95			);
96			if (!writableOnExitRaw) {
97				throw new MalformedSpecError(
98					`x-transitions.states.${name}.writableOnExit must be an object`,
99				);
100			}
101			const writableOnExit = Object.create(null) as Record<string, string[]>;
102			for (const [target, fields] of Object.entries(writableOnExitRaw)) {
103				writableOnExit[target] = parseStringArray(
104					fields,
105					`x-transitions.states.${name}.writableOnExit.${target}`,
106				);
107			}
108			states[name] = {
109				to: parseStringArray(state.to, `x-transitions.states.${name}.to`),
110				frozen: frozen === true,
111				writableOnExit,
112			};
113		}
114	
115		// A `to` naming a state that does not exist can never be satisfied, so it is
116		// a typo rather than a rule. Catch it at parse time, not at the write.
117		for (const [name, state] of Object.entries(states)) {
118			for (const target of state.to) {
119				if (!Object.hasOwn(states, target)) {
120					throw new MalformedSpecError(
121						`x-transitions.states.${name}.to names unknown state "${target}"`,
122					);
123				}
124			}
125			for (const target of Object.keys(state.writableOnExit)) {
126				if (!state.to.includes(target)) {
127					throw new MalformedSpecError(
128						`x-transitions.states.${name}.writableOnExit names non-transition target "${target}"`,
129					);
130				}
131			}
132		}
133		return { field, states };
134	}
135	
136	/**
137	 * Decide one write against a parsed spec.
138	 *
139	 * `committed` is the row as it stands; `patch` is the EFFECTIVE change about to
140	 * be written — not a proposal. Validating the patch rather than a proposal is
141	 * load-bearing: the permission pass strips approval-held fields and the
142	 * ownership merge rewrites others, so a rule fed the proposal can accept a
143	 * combination that never reaches the table (a header/line total pair whose
144	 * header is held for approval, leaving the line to commit against a stale
145	 * header). Only the patch is what actually lands.
146	 *
147	 * Returns a violation reason, or null for "legal".
148	 */
149	export function evaluateTransition(args: {
150		spec: TransitionSpec;
151		committed: Record<string, unknown>;
152		patch: Record<string, unknown>;
153	}): string | null {
154		const { spec, committed, patch } = args;
155		const fromRaw = committed[spec.field];
156		if (typeof fromRaw !== "string") return null;
157		const from = Object.hasOwn(spec.states, fromRaw)
158			? spec.states[fromRaw]
159			: undefined;
160		// An undeclared current state gets no opinion: a spec can only describe the
161		// states it names, and failing closed here would freeze every row whose value
162		// predates the rule. An undeclared TARGET is still denied below, because it
163		// can never appear in a declared `to` list.
164		if (!from) return null;
165	
166		let movingTo: string | null = null;
167		if (Object.hasOwn(patch, spec.field)) {
168			const next = patch[spec.field];
169			if (typeof next !== "string") {
170				return `state field "${spec.field}" must be a string`;
171			}
172			if (next !== fromRaw) movingTo = next;
173		}
174	
175		if (movingTo !== null && !from.to.includes(movingTo)) {
176			return `illegal transition ${fromRaw} -> ${movingTo}`;
177		}
178	
179		if (from.frozen) {
180			const exempt = new Set<string>([spec.field]);
181			if (movingTo !== null) {
182				for (const f of from.writableOnExit[movingTo] ?? []) exempt.add(f);
183			}
184			const illegal = Object.keys(patch).filter(
185				(f) =>
186					!exempt.has(f) &&
187					!isDeepStrictEqual(committed[f] ?? null, patch[f] ?? null),
188			);
189			if (illegal.length > 0) {
190				return `frozen in state "${fromRaw}": cannot write ${illegal.sort().join(", ")}`;
191			}
192		}
193		return null;
194	}
195	
196	/** Read a spec off a type's `metadata_schema`. Null ⇒ the type declares none. */
197	export function specFromMetadataSchema(
198		rawSchema: unknown,
199	): TransitionSpec | null {
200		const schema = asRecord(
201			typeof rawSchema === "string" ? JSON.parse(rawSchema) : rawSchema,
202		);
203		const raw = schema?.["x-transitions"];
204		if (raw === undefined) return null;
205		return parseTransitionSpec(raw);
206	}
