/**
 * SPIKE: how does same-row contention scale with LOCK HOLD time?
 *
 * `updateEntity` takes `SELECT ... FOR UPDATE` inside its transaction and holds
 * that lock until commit. A write rule runs inside that window, so a rule adds
 * its execution time to the lock hold. The isolate costs a measured 4.5ms p50,
 * which is fine as latency — the open question is what it does to THROUGHPUT
 * when several writers contend for one row.
 *
 * This isolates the one variable: it holds the row lock for a fixed duration
 * with `pg_sleep` and varies concurrency. What consumes the time does not matter
 * to the lock, so a sleep is a faithful stand-in for an isolate run.
 *
 * Not a pass/fail test — it prints a table. Run with:
 *   bunx vitest run src/__tests__/integration/authz/spike-lock-hold.test.ts
 */

import { beforeAll, describe, it } from "vitest";
import { createEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

const HOLD_MS = [0, 1, 4.5, 10];
const CONCURRENCY = [1, 4, 16];
const OPS_PER_WORKER = 5;

function pct(sorted: number[], p: number): number {
	if (sorted.length === 0) return 0;
	const i = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
	return sorted[i];
}

/** One locked read-modify-write, holding the row lock for `holdMs`. */
async function lockedWrite(entityId: number, holdMs: number): Promise<number> {
	const sql = getTestDb();
	const started = performance.now();
	await sql.begin(async (tx) => {
		await tx`SELECT id FROM entities WHERE id = ${entityId} FOR UPDATE`;
		if (holdMs > 0) await tx`SELECT pg_sleep(${holdMs / 1000})`;
		await tx`UPDATE entities SET updated_at = current_timestamp WHERE id = ${entityId}`;
	});
	return performance.now() - started;
}

describe("SPIKE: row-lock hold vs concurrency", () => {
	let entityId: number;

	beforeAll(async () => {
		await cleanupTestDatabase();
		const sql = getTestDb();
		const org = await createTestOrganization({ name: "Lock Hold Spike" });
		const user = await createTestUser();
		await addUserToOrganization(user.id, org.id, "owner");
		await sql`
      INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
                                created_at, updated_at)
      VALUES (${org.id}, 'hot', 'hot', ${sql.json({ type: "object" })},
              current_timestamp, current_timestamp)
    `;
		const e = await createEntity({
			entity_type: "hot",
			name: "HOT-ROW",
			organization_id: org.id,
			created_by: user.id,
			metadata: { n: 0 },
		} as Parameters<typeof createEntity>[0]);
		entityId = e.id;
	});

	it("measures throughput and latency across hold times", async () => {
		// Warm the pool and the plan cache so the first cell is not an outlier.
		await Promise.all([0, 0, 0, 0].map(() => lockedWrite(entityId, 0)));

		const lines: string[] = [];
		lines.push("");
		lines.push("hold_ms  workers  ops  wall_ms  ops/s   p50_ms  p95_ms  max_ms");
		lines.push("-------  -------  ---  -------  ------  ------  ------  ------");

		for (const holdMs of HOLD_MS) {
			for (const workers of CONCURRENCY) {
				const started = performance.now();
				const results = await Promise.all(
					Array.from({ length: workers }, async () => {
						const own: number[] = [];
						for (let i = 0; i < OPS_PER_WORKER; i++) {
							own.push(await lockedWrite(entityId, holdMs));
						}
						return own;
					}),
				);
				const wall = performance.now() - started;
				const all = results.flat().sort((a, b) => a - b);
				const ops = all.length;
				lines.push(
					[
						String(holdMs).padStart(7),
						String(workers).padStart(9),
						String(ops).padStart(5),
						wall.toFixed(1).padStart(9),
						(ops / (wall / 1000)).toFixed(1).padStart(7),
						pct(all, 50).toFixed(2).padStart(8),
						pct(all, 95).toFixed(2).padStart(8),
						all[all.length - 1].toFixed(2).padStart(8),
					].join(""),
				);
			}
		}
		lines.push("");
		// biome-ignore lint/suspicious/noConsole: spike output is the deliverable
		console.log(lines.join("\n"));
	}, 300_000);
});

