/**
 * What does one host-bridge round trip cost from inside the isolate?
 *
 * Mirrors run-script.ts's dispatch shape:
 *   __sdk_dispatch.apply(undefined, [path, payload], { result: { promise: true, copy: true } })
 *
 * Baseline is a bridge-free rule (the 0.63ms figure). Each row adds N calls to a
 * host function that returns a small row-shaped object, so the delta per call is
 * the marginal cost of a keyed read inside the held row lock.
 */
import ivm from "isolated-vm";
import os from "node:os";

const CALL_COUNTS = [0, 1, 2, 3, 5, 10];
const OPS = 200;

// Stands in for a keyed read: returns a small row, no real IO.
function hostRead(id) {
  return { id, status: "active", credit_limit: 25000, on_hold: false };
}

function guestSource(nCalls) {
  return `
    async function rule(ctx) {
      let reads = 0;
      ${Array.from({ length: nCalls }, (_, i) => `
      {
        const r = await __dispatch.apply(undefined, [${i}], { result: { promise: true, copy: true } });
        if (r && r.on_hold) return "customer on hold";
        reads++;
      }`).join("")}
      const c = ctx.committed, p = ctx.patch;
      if (c.status === "posted") return "frozen";
      let sum = 0;
      for (const line of p.lines) sum += line.amount;
      if (sum !== p.header_net) return "lines do not sum to header";
      return null;
    }
    rule({
      committed: { status: "draft", header_net: 3 },
      patch: { header_net: 3, lines: [{ amount: 1 }, { amount: 2 }] },
    });
  `;
}

async function oneRun(nCalls) {
  const isolate = new ivm.Isolate({ memoryLimit: 128 });
  try {
    const context = await isolate.createContext();
    if (nCalls > 0) {
      const jail = context.global;
      await jail.set("__dispatch", new ivm.Reference(async (id) => hostRead(id)));
    }
    const script = await isolate.compileScript(guestSource(nCalls));
    await script.run(context, { timeout: 1000, promise: true, copy: true });
  } finally {
    isolate.dispose();
  }
}

function pct(sorted, p) {
  if (sorted.length === 0) return 0;
  const i = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[i];
}

async function measure(nCalls) {
  const lat = [];
  for (let i = 0; i < OPS; i++) {
    const t0 = performance.now();
    await oneRun(nCalls);
    lat.push(performance.now() - t0);
  }
  return lat.sort((a, b) => a - b);
}

await measure(0); // warm
await measure(1);

const out = [];
out.push("");
out.push("host_calls  p50_ms  p95_ms  delta_vs_0  per_call");
out.push("----------  ------  ------  ----------  --------");

let base = null;
for (const n of CALL_COUNTS) {
  const lat = await measure(n);
  const p50 = pct(lat, 50);
  if (base === null) base = p50;
  const delta = p50 - base;
  out.push(
    [
      String(n).padStart(10),
      p50.toFixed(3).padStart(8),
      pct(lat, 95).toFixed(3).padStart(8),
      (delta >= 0 ? "+" : "") + delta.toFixed(3).padStart(9),
      (n === 0 ? "—" : (delta / n).toFixed(4)).padStart(10),
    ].join(""),
  );
}
out.push("");
out.push(`ops each: ${OPS}   cpus: ${os.cpus().length}   node ${process.version}`);
out.push("");
console.log(out.join("\n"));

