			clearInterval(timer);

			latencies.sort((a, b) => a - b);
			const at = (p: number) =>
				latencies[Math.min(latencies.length - 1, Math.floor(latencies.length * p))];
			const expectedTicks = Math.floor(DURATION_MS / HEARTBEAT_MS);
			const maxGap = gaps.length ? Math.max(...gaps) : Number.NaN;

