1	/**
2	 * Compiles a TypeScript user-script via esbuild, runs it in a V8 isolate, and
3	 * bridges SDK calls back to the host. Output is bounded per-purpose: interactive
4	 * return values are capped at 1 MB (an oversized value is replaced by a bounded
5	 * `returnValuePreview` head plus a report, never shipped in full to the model),
6	 * console logs are capped at 64 KB and the guest console bridge is disabled
7	 * once full. Each single
8	 * host↔guest bridge message (SDK payload, SDK result, or return envelope) is
9	 * capped at 4 MB — a larger message, or exhausting the 200-call quota,
10	 * terminates the run by disposing the isolate (uncatchable by the guest).
11	 * Extracted named exports keep the old hard-fail semantics because a partial
12	 * schema would be worse than none. Other caps: 180s wall-clock max
13	 * (device-bound operations may wait up to ~155s), and 30s per `ctx.sleep()`.
14	 * `client.org()` is stateless — each guest call carries
15	 * `orgPath` so the host re-walks org swaps without holding refs.
16	 */
17	
18	import type { ClientSDK } from "./client-sdk";
19	import { ClientSdkActionError } from "./namespaces/action-call";
20	import { METHOD_METADATA, type MethodAccess } from "./method-metadata";
21	import type { ToolAccessLevel } from "../auth/tool-access";
22	import { enumerateSDKManifest, type SDKMode } from "./sdk-manifest";
23	import { McpScopeRequiredError } from "../tools/access-control";
24	
25	export interface RunLimits {
26		memoryMb?: number;
27		timeoutMs?: number;
28		sdkCallQuota?: number;
29		/** Preview threshold and byte cap for interactive returns; extracted exports hard-fail instead. */
30		outputBytes?: number;
31		/** Cap for captured console logs; messages past it are dropped. */
32		logBytes?: number;
33		/** Serialized cap for EACH of `sdk_call_trace` and `side_effect_preview`; oldest entries are dropped past it. */
34		traceBytes?: number;
35		/** Single-message cap for host↔guest bridge traffic; a larger message terminates the run. */
36		messageBytes?: number;
37	}
38	
39	/** What the host kept when a return value exceeded `outputBytes` and became a preview. */
40	interface ReturnPreviewInfo {
41		total_bytes: number;
42		kept_bytes: number;
43	}
44	
45	/**
46	 * Whether one SDK call is skipped-and-recorded rather than dispatched.
47	 *
48	 * Exported so the capture contract is pinned by a test against THIS expression
49	 * rather than a copy of it — a mirrored predicate in a test can never catch a
50	 * regression here.
51	 */
52	export function isSkippedUnderDryRun(args: {
53		dryRun?: boolean;
54		dryRunDispatchPaths?: readonly string[];
55		access: string;
56		path: string;
57	}): boolean {
58		if (args.dryRun !== true) return false;
59		if (args.access === "read") return false;
60		return !args.dryRunDispatchPaths?.includes(args.path);
61	}
62	
63	export interface RunScriptOptions {
64		source: string;
65		context?: Record<string, unknown>;
66		/**
67		 * Preview mode for full-SDK scripts. Read calls still execute so scripts can
68		 * inspect state, but write/external SDK calls are skipped and returned in
69		 * `sideEffectPreview` instead of mutating state or reaching external systems.
70		 */
71		dryRun?: boolean;
72		/**
73		 * SDK paths that still DISPATCH under {@link dryRun}, because the handler
74		 * behind them is itself capture-aware and refuses its own writes.
75		 *
76		 * This exists for exactly one case: an eval replay is told to finalize via
77		 * `client.automations.completeWindow`, and the blanket skip would swallow that
78		 * call — leaving the run with no window, so it gets nudged into a second
79		 * full replay and then failed with "finished without calling run_sdk". The
