/**
 * The entity-row VALIDATION seam.
 *
 * `patchEntityRows` is the single physical writer for entity rows (the
 * `check-entity-write-funnel` gate proves no raw entity SQL lives outside
 * `entity-management.ts`). It is therefore the only place every write
 * converges, and the only place a state invariant can be enforced without
 * depending on 20-odd callers each remembering to ask.
 *
 * Enforcement is structural rather than conventional: `patchEntityRows` accepts
 * only a {@link ValidatedEntityRowPatch}, which this module alone can mint. A
 * caller that forgets to validate does not slip through — it fails to compile.
 *
 * Two reasons validation lives HERE and not in `runMutationGate`:
 *
 *  1. The gate answers a PERMISSION question (may this principal write this
 *     field) and is keyed on `principalKind` + ownership. Validation answers
 *     "is the resulting state legal", which has no principal in it.
 *  2. The gate runs BEFORE approval-held fields are stripped and before the
 *     ownership merge rewrites the patch. It therefore judges a proposal, not
 *     what commits. This seam sees the effective patch — the exact bytes about
 *     to hit the table — so it cannot be fooled by either transformation.
 */

import { type DbClient, pgBigintArray } from "../db/client";
import type {
	EntityRowInsert,
	EntityRowPatch,
} from "../utils/entity-management";
import { type EntityRuleRow, runEntityRules } from "./entity-rule-executor";

declare const validatedBrand: unique symbol;

/**
 * An `EntityRowPatch` that has passed validation (or been explicitly exempted).
 * Only this module can produce one — the brand has no public constructor, so
 * `patchEntityRows` cannot be called with an unchecked patch.
 */
export type ValidatedEntityRowPatch = EntityRowPatch & {
	readonly [validatedBrand]: true;
};

/** Thrown when a patch would produce an illegal state. */
export class EntityRowValidationError extends Error {}

/**
 * Patch columns a transition spec can never govern: platform bookkeeping that
 * no tenant declares in its schema. A patch touching only these skips
 * validation entirely — no spec read, no evaluation — which is what keeps the
 * common write off the validation path.
 *
 * The complement (`metadata`, `name`, `slug`, `parentId`, `content`,
 * `softDelete`) IS governed: freezing a document has to stop a rename and a
 * delete, not merely a metadata edit.
 */
const UNGOVERNED_COLUMNS: ReadonlySet<string> = new Set([
	"currentViewTemplateVersionId",
	"fieldControls",
	"enabledClassifiers",
	"embedding",
	"contentHash",
]);

/** Reserved `$`-names the spec sees for non-metadata columns. */
const RESERVED_COLUMN_NAMES: Readonly<Record<string, string>> = {
	name: "$name",
	slug: "$slug",
	parentId: "$parent_id",
	content: "$content",
	softDelete: "$deleted",
};

function touchesGovernedColumn(patch: EntityRowPatch): boolean {
	return Object.keys(patch).some((k) => !UNGOVERNED_COLUMNS.has(k));
}

/**
 * Flatten a patch into the single namespace a spec reasons about: metadata keys
 * plus reserved `$`-names for columns.
 *
 * `patch.metadata` is the fully merged metadata object, not a delta, so most of
 * its keys are unchanged values. A rule compares `next` against `committed` and
 * ignores no-ops, which is what makes passing the whole object correct rather
 * than a source of false violations. Note this means `ctx.changed(f)` is true
 * for any key present in the merged metadata, not only genuinely altered ones.
 */
function flatten(
	patch: EntityRowPatch,
	metadata: Record<string, unknown> | null | undefined,
): Record<string, unknown> {
	const flat: Record<string, unknown> = { ...(metadata ?? {}) };
	for (const [column, reserved] of Object.entries(RESERVED_COLUMN_NAMES)) {
		if (Object.hasOwn(patch, column)) {
			flat[reserved] = patch[column as keyof EntityRowPatch] ?? null;
		}
	}
	return flat;
}

interface CommittedRow {
	id: number;
	metadata: unknown;
	rules_compiled: string | null;
	name: string | null;
	slug: string | null;
	parent_id: string | number | null;
	content: string | null;
	deleted_at: Date | null;
}

function committedState(row: CommittedRow): Record<string, unknown> {
	const metadata = (
		typeof row.metadata === "string"
			? JSON.parse(row.metadata)
			: (row.metadata ?? {})
	) as Record<string, unknown>;
	return {
		...metadata,
		$name: row.name ?? null,
		$slug: row.slug ?? null,
		$parent_id: row.parent_id == null ? null : Number(row.parent_id),
		$content: row.content ?? null,
		$deleted: row.deleted_at != null,
	};
}

/**
 * Validate an effective patch against every target row's declared write rules,
 * returning the patch branded for {@link patchEntityRows}.
 *
 * Queries only the caller's handle — never `getDb()`. A pooled query from
 * inside an entity write transaction is the #2818 deadlock (every pool session
 * parked `idle in transaction` on the same statement), and it would also read a
 * different snapshot than the one being written.
 *
 * Rows are grouped by their type's compiled rule so each distinct rule runs in
 * ONE isolate over its whole group. Per-row isolates do not scale — measured at
 * ~300 evals/sec, or ~21s for a 5,000-row sync, against ~13.5ms for the same
 * rows batched.
 *
 * @throws EntityRowValidationError when a rule denies the write, when a rule
 * crashes or times out (fail closed: a rule that did not finish cannot bless a
 * write), or when it returns an unusable verdict.
 */
export async function validateEntityRowPatch(params: {
	tx: DbClient;
	ids: number[];
	patch: EntityRowPatch;
}): Promise<ValidatedEntityRowPatch> {
	const { tx, ids, patch } = params;
	const branded = patch as ValidatedEntityRowPatch;
	if (ids.length === 0) return branded;
	// Fast path: nothing a rule could govern, so no read and no evaluation.
	if (!touchesGovernedColumn(patch)) return branded;

	// The pool runs with `fetch_types: false`, so a raw JS array binds as
	// "malformed array literal". Bind the formatted `{n,n}` text and cast, exactly
	// as `patchEntityRows` itself does.
	//
	// `rules_compiled` rides the join this query already makes, so rule lookup
	// costs no extra round trip.
	const rows = await tx<CommittedRow>`
    SELECT e.id, e.metadata, e.name, e.slug, e.parent_id, e.content,
           e.deleted_at, et.rules_compiled
    FROM entities e
    JOIN entity_types et ON et.id = e.entity_type_id
    WHERE e.id = ANY(${pgBigintArray(ids)}::bigint[])
  `;

	// One group per distinct compiled rule. Types without rules never reach an
	// isolate at all, which keeps an unruled org's writes exactly as cheap as
	// they are today.
	const groups = new Map<string, { ids: number[]; rows: EntityRuleRow[] }>();
	const flatPatch = flatten(patch, patch.metadata);
	for (const row of rows) {
		if (!row.rules_compiled) continue;
		const group = groups.get(row.rules_compiled) ?? { ids: [], rows: [] };
		group.ids.push(row.id);
		group.rows.push({ committed: committedState(row), patch: flatPatch });
		groups.set(row.rules_compiled, group);
	}
	if (groups.size === 0) return branded;

	for (const [compiled, group] of groups) {
		const verdicts = await runEntityRules({
			compiled,
			rows: group.rows,
			op: "update",
		});
		for (const [index, verdict] of verdicts.entries()) {
			if (verdict.outcome === "deny") {
				throw new EntityRowValidationError(
					`entity ${group.ids[index]}: ${verdict.reason}`,
				);
			}
			if (verdict.outcome === "escalate") {
				// Escalation routing (hold the named fields, open an approval, resolve
				// an approver) is not wired yet. Failing closed rather than allowing
				// the write: silently committing a change the rule asked a human to
				// review would be the worst of the three options, and a rule author
				// would have no way to notice.
				throw new EntityRowValidationError(
					`entity ${group.ids[index]}: escalation is not wired yet ` +
						`(rule asked for approval of ${verdict.fields.join(", ")}: ${verdict.reason})`,
				);
			}
		}
	}
	return branded;
}

/**
 * Mint a validated patch WITHOUT running validation.
 *
 * For platform bookkeeping that legitimately sits outside tenant state rules —
 * eval scaffolding, ACL graph upkeep, merge-ledger transitions. Deliberately
 * named and greppable: an exemption should be visible in review, unlike the
 * implicit bypass that every direct `patchEntityRows` caller enjoyed before
 * this seam existed.
 *
 * @param reason why this write is not subject to state validation.
 */
export function unvalidatedEntityRowPatch(params: {
	patch: EntityRowPatch;
	reason: string;
}): ValidatedEntityRowPatch {
	return params.patch as ValidatedEntityRowPatch;
}

// ---------------------------------------------------------------------------
// Inserts
//
// The brand above made skipping validation a compile error for the UPDATE
// writer, and stopped there — so creates went straight to the table. That made
// every rule trivially routable: an agent denied a `draft -> posted` update
// simply creates the document already posted. Proven, with the contrast case,
// in `spike-create-bypasses-validation.test.ts`.
//
// The fix is not a new mechanism, it is the SAME brand on the second writer. A
// create is an update from nothing: `committed` is `{}`, so `changed(f)` is true
// for every field being set and a rule's transition check rejects a document
// born in a state nothing exits into.
// ---------------------------------------------------------------------------

/**
 * An `EntityRowInsert` that has passed validation (or been explicitly exempted).
 * Shares {@link validatedBrand} with {@link ValidatedEntityRowPatch}: one brand,
 * two shapes, so there is one thing to reason about rather than two.
 */
export type ValidatedEntityRowInsert = EntityRowInsert & {
	readonly [validatedBrand]: true;
};

/**
 * Validate a pending insert against its type's write rules, returning the row
 * branded for {@link insertEntityRow}.
 *
 * Reads `entity_types` directly rather than joining through `entities`, because
 * the row does not exist yet — that is the only structural difference from the
 * update path.
 *
 * @throws EntityRowValidationError when the rule denies the create.
 */
export async function validateEntityRowInsert(params: {
	tx: DbClient;
	row: EntityRowInsert;
}): Promise<ValidatedEntityRowInsert> {
	const { tx, row } = params;
	const branded = row as ValidatedEntityRowInsert;

	const types = await tx<{ rules_compiled: string | null }>`
    SELECT rules_compiled FROM entity_types WHERE id = ${row.entityTypeId}
  `;
	const compiled = types[0]?.rules_compiled;
	if (!compiled) return branded;

	const [verdict] = await runEntityRules({
		compiled,
		op: "create",
		rows: [
			{
				// Nothing is committed yet. An absent `committed` is what lets one
				// rule serve both paths without branching on `op`.
				committed: {},
				patch: flatten(
					{
						name: row.name,
						slug: row.slug,
						parentId: row.parentId ?? null,
						content: row.content ?? null,
					},
					row.metadata,
				),
			},
		],
	});

	if (verdict?.outcome === "deny") {
		throw new EntityRowValidationError(
			`new ${row.slug}: ${verdict.reason}`,
		);
	}
	if (verdict?.outcome === "escalate") {
		throw new EntityRowValidationError(
			`new ${row.slug}: escalation is not wired yet ` +
				`(rule asked for approval of ${verdict.fields.join(", ")}: ${verdict.reason})`,
		);
	}
	return branded;
}

/**
 * Mint a validated insert WITHOUT running validation.
 *
 * Same contract as {@link unvalidatedEntityRowPatch}: platform bookkeeping that
 * legitimately sits outside tenant rules, named so the exemption is greppable
 * and visible in review.
 *
 * @param reason why this create is not subject to write rules.
 */
export function unvalidatedEntityRowInsert(params: {
	row: EntityRowInsert;
	reason: string;
}): ValidatedEntityRowInsert {
	return params.row as ValidatedEntityRowInsert;
}

/**
 * Executes a type's compiled write rules at the entity row-write seam.
 *
 * BATCH-SHAPED BY CONSTRUCTION. One isolate evaluates every row in the batch,
 * not one isolate per row. Measured on node 22: per-row tops out near 300
 * evals/sec and takes ~21s for 5,000 rows, while the same 5,000 rows share one
 * isolate in ~13.5ms — the ~3ms fixed cost (compile lookup, isolate create,
 * context copy, dispose) amortises to ~0.002ms marginal per row. The rule still
 * runs once per row; only the instantiation is shared.
 *
 * `validateEntityRowPatch` is already batch-shaped (`ids: number[]`), so this
 * matches a shape the seam already had.
 *
 * A rule needs no ClientSDK: `deny` and `escalate` are pure control flow and
 * live entirely guest-side (see {@link RULE_RUNNER}), so nothing crosses an
 * `ivm.Reference`. The stub below stands in for an `sdkMode: "none"` that does
 * not exist yet — `SDKMode` is `"read" | "full"` — which is also what would make
 * a read budget enforceable by construction rather than by convention.
 */

import type { ClientSDK } from "../sandbox/client-sdk";
import { runScript } from "../sandbox/run-script";

/**
 * Wall-clock budget for one BATCH. Generous relative to the ~3ms + 0.002ms/row
 * cost curve, because it is spent holding row locks; {@link MAX_RULE_BATCH}
 * bounds how much work can sit behind it.
 */
const RULE_BATCH_TIMEOUT_MS = 2_000;

/**
 * Rows per isolate invocation. One batch blocks the event loop for its whole
 * duration — 5,000 rows measured at 13.5ms — so this caps a single uninterrupted
 * block at roughly 5ms. Unbounded batching would not remove the starvation
 * risk, only relocate it.
 */
export const MAX_RULE_BATCH = 2_000;

export type EntityRuleVerdict =
	| { outcome: "allow" }
	| { outcome: "deny"; reason: string }
	| { outcome: "escalate"; fields: string[]; reason: string };

export interface EntityRuleRow {
	/** The row as committed, read under the lock. `{}` for a create. */
	committed: Record<string, unknown>;
	/** The EFFECTIVE patch — post field-merge, so approval-held fields are gone. */
	patch: Record<string, unknown>;
}

export interface EntityRuleBatch {
	/** Compiled JS for the type's rule module (`entity_types.rules_compiled`). */
	compiled: string;
	rows: EntityRuleRow[];
	op: "create" | "update" | "delete";
	timeoutMs?: number;
}

/**
 * Guest-side runner wrapped around the author's module.
 *
 * This is what removes the need for host bridges. `deny` throws a tagged error
 * the runner catches; `escalate` assigns a local. Both are ordinary JS inside
 * the isolate, so the whole verdict array crosses the boundary once, on return.
 *
 * `ctx.actor` is deliberately ABSENT in this version. This seam judges "is the
 * resulting state legal", which has no principal in it — the permission question
 * (may this principal write this field) is answered earlier by `runMutationGate`.
 * Threading an actor here would also mean changing every caller of
 * `validateEntityRowPatch`, several of which are platform bookkeeping with no
 * actor at all. Actor-scoped denial is a deliberate follow-up, not an oversight.
 */
const RULE_RUNNER = `
export default async (ctx) => {
  const verdicts = [];
  for (const row of ctx.rows) {
    let verdict = { outcome: "allow" };
    const api = {
      committed: row.committed,
      patch: row.patch,
      next: { ...row.committed, ...row.patch },
      op: ctx.op,
      changed: (f) => Object.prototype.hasOwnProperty.call(row.patch, f),
      deny: (reason) => {
        const err = new Error(String(reason));
        err.__lobuDeny = true;
        throw err;
      },
      escalate: (fields, reason) => {
        verdict = {
          outcome: "escalate",
          fields: Array.isArray(fields) ? fields : [fields],
          reason: String(reason),
        };
      },
    };
    try {
      await __lobuRule(api);
    } catch (err) {
      if (err && err.__lobuDeny) verdict = { outcome: "deny", reason: err.message };
      else throw err;
    }
    verdicts.push(verdict);
  }
  return verdicts;
};`;

/**
 * Wrap an author's compiled module so its default export is reachable as
 * `__lobuRule` and the runner above drives it.
 *
 * Kept as a named export so the apply path can store exactly what runs, rather
 * than re-deriving the wrapper at write time.
 */
export function wrapCompiledRule(compiledModule: string): string {
	return `${compiledModule}\nconst __lobuRule = (typeof module !== "undefined" && module.exports && module.exports.default) || (typeof exports !== "undefined" && exports.default);\n${RULE_RUNNER}`;
}

/**
 * Evaluate one type's rule against a batch of rows.
 *
 * Returns one verdict per row, positionally. Never throws on a rule's own deny —
 * the caller decides whether a deny becomes an error (enforcing) or a log line
 * (inert), which keeps the inert-then-arm rollout a caller-side flag rather than
 * a second code path.
 *
 * A rule that crashes or times out FAILS CLOSED. It ran holding row locks and we
 * cannot distinguish a bug from a deliberate infinite loop, so the write does not
 * proceed on the strength of a rule that did not finish.
 */
export async function runEntityRules(
	batch: EntityRuleBatch,
): Promise<EntityRuleVerdict[]> {
	if (batch.rows.length === 0) return [];
	if (batch.rows.length > MAX_RULE_BATCH) {
		const out: EntityRuleVerdict[] = [];
		for (let i = 0; i < batch.rows.length; i += MAX_RULE_BATCH) {
			out.push(
				...(await runEntityRules({
					...batch,
					rows: batch.rows.slice(i, i + MAX_RULE_BATCH),
				})),
			);
		}
		return out;
	}

	// Placeholder for `sdkMode: "none"`. A rule declares no reads, so nothing
	// behind this stub is reachable from the guest.
	const noSdk = { log: () => undefined } as unknown as ClientSDK;

	const result = await runScript({
		source: wrapCompiledRule(batch.compiled),
		sdk: noSdk,
		context: { rows: batch.rows, op: batch.op },
		limits: { timeoutMs: batch.timeoutMs ?? RULE_BATCH_TIMEOUT_MS },
	});

	if (!result.success) {
		const detail = result.error
			? `${result.error.name}: ${result.error.message}`
			: "rule did not complete";
		return batch.rows.map(() => ({
			outcome: "deny" as const,
			reason: `rule failed: ${detail}`,
		}));
	}

	const verdicts = result.returnValue;
	if (!Array.isArray(verdicts) || verdicts.length !== batch.rows.length) {
		return batch.rows.map(() => ({
			outcome: "deny" as const,
			reason: "rule returned no usable verdict",
		}));
	}
	return verdicts as EntityRuleVerdict[];
}

