33		addUserToOrganization,
34		createTestAgent,
35		createTestOrganization,
36		createTestUser,
37	} from "../../setup/test-fixtures";
38	
39	const INVOICE_RULE = `
40	const ALLOWED = { draft: ["issued"], issued: ["posted"], posted: [] };
41	const FROZEN = ["issued", "posted"];
42	const WRITABLE_ON_EXIT = { "issued->posted": ["einvoice_uuid"] };
43	const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
44	
45	export default (row) => {
46	  if (row.op === "create") {
47	    if (row.next.status !== "draft") {
48	      row.deny("an invoice is created in draft, not " + row.next.status);
49	    }
50	    return;
51	  }
52	  const from = row.committed.status;
53	  const to = row.next.status;
54	  if (from !== to && !(ALLOWED[from] || []).includes(to)) {
55	    row.deny("cannot move " + from + " -> " + to);
56	  }
57	  if (row.next.amount > 50000) {
58	    row.escalate(["amount"], "an invoice over 50k needs sign-off");
59	  }
60	
61	  if (!FROZEN.includes(from)) return;
62	  const permitted = ["status"].concat(WRITABLE_ON_EXIT[from + "->" + to] || []);
63	  for (const field of Object.keys(row.patch)) {
64	    if (permitted.includes(field)) continue;
65	    if (same(row.committed[field], row.patch[field])) continue;
66	    row.deny(from + " is frozen: " + field + " is not writable");
67	  }
68	};
69	`;
