81			memberRole: "owner",
82			agentId: opts.agentId ?? null,
83			isAuthenticated: true,
84			clientId: null,
85			scopes: ["mcp:read", "mcp:write", "mcp:admin"],
86			tokenType: "oauth",
87			scopedToOrg: true,
88			allowCrossOrg: false,
89		} as unknown as ToolContext;
90	}
91	
92	async function readMetadata(id: number): Promise<Record<string, unknown>> {
93		const sql = getTestDb();
94		const rows = await sql<{ metadata: unknown }[]>`
95	    SELECT metadata FROM entities WHERE id = ${id}
96	  `;
97		const raw = rows[0].metadata;
98		return (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
99			string,
100			unknown
101		>;
102	}
