1	/**
2	 * The entity-row VALIDATION seam.
3	 *
4	 * `patchEntityRows` is the single physical writer for entity rows (the
5	 * `check-entity-write-funnel` gate proves no raw entity SQL lives outside
6	 * `entity-management.ts`). It is therefore the only place every write
7	 * converges, and the only place a state invariant can be enforced without
8	 * depending on 20-odd callers each remembering to ask.
9	 *
10	 * Enforcement is structural rather than conventional: `patchEntityRows` accepts
11	 * only a {@link ValidatedEntityRowPatch}, which this module alone can mint. A
12	 * caller that forgets to validate does not slip through — it fails to compile.
13	 *
14	 * Two reasons validation lives HERE and not in `runMutationGate`:
15	 *
16	 *  1. The gate answers a PERMISSION question (may this principal write this
17	 *     field) and is keyed on `principalKind` + ownership. Validation answers
18	 *     "is the resulting state legal", which has no principal in it.
19	 *  2. The gate runs BEFORE approval-held fields are stripped and before the
20	 *     ownership merge rewrites the patch. It therefore judges a proposal, not
21	 *     what commits. This seam sees the effective patch — the exact bytes about
22	 *     to hit the table — so it cannot be fooled by either transformation.
23	 */
24	
25	import { type DbClient, pgBigintArray } from "../db/client";
26	import type {
27		EntityRowInsert,
28		EntityRowPatch,
29	} from "../utils/entity-management";
30	import { type EntityRuleRow, runEntityRules } from "./entity-rule-executor";
31	
32	declare const validatedBrand: unique symbol;
33	
34	/**
35	 * An `EntityRowPatch` that has passed validation (or been explicitly exempted).
36	 * Only this module can produce one — the brand has no public constructor, so
37	 * `patchEntityRows` cannot be called with an unchecked patch.
38	 */
39	export type ValidatedEntityRowPatch = EntityRowPatch & {
40		readonly [validatedBrand]: true;
41	};
42	
43	/** What a rule decided, carried on the error so a caller can route it. */
44	export interface EntityRowValidationVerdict {
45		outcome: "deny" | "escalate";
46		reason: string;
47		/** Fields the rule named when escalating. Empty for a deny. */
48		fields: string[];
49		/** The row judged, or null for a create — there is no row yet. */
50		entityId: number | null;
51	}
52	
53	/**
54	 * Thrown when a patch would produce an illegal state.
55	 *
56	 * Throwing rather than returning a verdict is deliberate: it makes failing
57	 * closed the DEFAULT for every caller. Only `updateEntity` has approval
58	 * machinery to route an escalation into, and it opts in by catching this and
59	 * reading {@link verdict}. Merge, link auto-create and eval scaffolding have
60	 * nowhere to queue a card, so for them a rule that asked for review must stop
