import { beforeAll, describe, expect, it } from "vitest";
import { compileEntityRule } from "../../../authz/entity-rule-executor";
import type { Env } from "../../../index";
import type { ToolContext } from "../../../tools/registry";
import { createEntity, updateEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import { addUserToOrganization, createTestOrganization, createTestUser } from "../../setup/test-fixtures";

// A rule doing the most obvious thing an author would write.
const RULE = `export default (row) => {
  if (row.op === "update" && row.changed("status")) {
    row.deny("status is frozen");
  }
};`;

const TEST_ENV = {} as Env;
let compiled: string;

describe("PROBE: does changed() mean changed?", () => {
  beforeAll(async () => { compiled = await compileEntityRule(RULE); }, 60_000);

  it("an update that does NOT touch status is denied anyway", async () => {
    await cleanupTestDatabase();
    const sql = getTestDb();
    const org = await createTestOrganization({ name: "Probe" });
    const user = await createTestUser();
    await addUserToOrganization(user.id, org.id, "owner");
    await sql`INSERT INTO entity_types (organization_id, slug, name, metadata_schema, rules_compiled, created_at, updated_at)
      VALUES (${org.id}, 'doc', 'doc', ${sql.json({ type: "object" })}, ${compiled}, current_timestamp, current_timestamp)`;

    const doc = await createEntity({
      entity_type: "doc", name: "D1", organization_id: org.id, created_by: user.id,
      metadata: { status: "draft", amount: 1 },
    } as Parameters<typeof createEntity>[0]);

    const ctx = { organizationId: org.id, userId: user.id, memberRole: "owner", agentId: null,
      isAuthenticated: true, clientId: null, scopes: ["mcp:read","mcp:write","mcp:admin"],
      tokenType: "oauth", scopedToOrg: true, allowCrossOrg: false } as unknown as ToolContext;

    // Touches ONLY `amount`. `status` is untouched, so this must be allowed.
    await updateEntity(doc.id, { metadata: { amount: 2 } }, TEST_ENV, ctx);
  }, 60_000);
});
EOF
