/**
 * Executes a type's compiled write rules at the entity row-write seam.
 *
 * BATCH-SHAPED BY CONSTRUCTION. One isolate evaluates every row in the batch,
 * not one isolate per row. A per-row design was built and measured first: it
 * tops out near 300 evals/sec, i.e. tens of seconds for a 5,000-row sync.
 *
 * Measured here on node 22, warm (all figures re-measured after the compile memo
 * in `run-script.ts` landed — an earlier revision of this comment quoted numbers
 * from a prototype and was wrong by 3x):
 *
 *   1 row          ~2.0ms      first call for a given rule ~14ms (one esbuild)
 *   50 rows        ~1.6ms
 *   1,000 rows     ~3.2ms      one full batch
 *   5,000 rows    ~29.7ms      five batches
 *
 * So roughly 1.6ms fixed per batch and ~0.002ms marginal per row. The rule still
 * runs once per row; only the instantiation is shared.
 *
 * `validateEntityRowPatch` is already batch-shaped (`ids: number[]`), so this
 * matches a shape the seam already had.
 *
 * A rule needs no ClientSDK: `deny` and `escalate` are pure control flow and
 * live entirely guest-side (see {@link RULE_RUNNER}), so nothing crosses an
 * `ivm.Reference`. The stub below stands in for an `sdkMode: "none"` that does
 * not exist yet — `SDKMode` is `"read" | "full"` — which is also what would make
 * a read budget enforceable by construction rather than by convention.
 */

import type { ClientSDK } from "../sandbox/client-sdk";
import { runScript } from "../sandbox/run-script";
import { compileSource } from "../utils/compiler-core";

/**
 * Wall-clock budget for one BATCH. Generous relative to the ~3ms + 0.002ms/row
 * cost curve, because it is spent holding row locks; {@link MAX_RULE_BATCH}
 * bounds how much work can sit behind it.
 */
const RULE_BATCH_TIMEOUT_MS = 2_000;

/**
 * Rows per isolate invocation. One batch blocks the event loop for its whole
 * duration, so this bounds a single uninterrupted block at ~3.2ms.
 *
 * 1,000 rather than a larger number because cost grows FASTER than linearly with
 * batch size — chunking is cheaper than one big call, not just kinder to the
 * event loop. Measured over the same 5,000 rows: at 2,000/batch the total was
 * 42.5ms with ~14-19ms blocks; at 1,000/batch it is 29.7ms with ~3.2ms blocks.
 * Unbounded batching would be worse on both axes.
 */
export const MAX_RULE_BATCH = 1_000;

export type EntityRuleVerdict =
	| { outcome: "allow" }
	| { outcome: "deny"; reason: string }
	| { outcome: "escalate"; fields: string[]; reason: string };

export interface EntityRuleRow {
	/** The row as committed, read under the lock. `{}` for a create. */
	committed: Record<string, unknown>;
	/** The EFFECTIVE patch — post field-merge, so approval-held fields are gone. */
	patch: Record<string, unknown>;
}

export interface EntityRuleBatch {
	/** Compiled JS for the type's rule module (`entity_types.rules_compiled`). */
	compiled: string;
	rows: EntityRuleRow[];
	/**
	 * `delete` is deliberately absent: soft-delete is the only delete that
	 * reaches this seam, and every soft-delete caller is currently exempted (see
	 * the KNOWN GAP in `deleteEntity`). Offering an op a rule can never observe
	 * would be a contract we do not honour.
	 */
	op: "create" | "update";
	timeoutMs?: number;
}

/**
 * Guest-side runner wrapped around the author's module.
 *
 * This is what removes the need for host bridges. `deny` throws a tagged error
 * the runner catches; `escalate` assigns a local. Both are ordinary JS inside
 * the isolate, so the whole verdict array crosses the boundary once, on return.
 *
 * `changed(field)` compares VALUES between `committed` and `next`. It cannot be
 * key presence: the seam hands a rule the fully merged value set, not a delta, so
 * `hasOwnProperty` is true for every metadata key on every metadata write, and a
 * rule asking `changed("status")` would fire on an unrelated edit to any other
 * field. That was a real defect — an update touching only `amount` was denied by
 * a rule that only guards `status` — reproduced end to end before this comparison
 * replaced it.
 *
 * `ctx.actor` is deliberately ABSENT in this version. This seam judges "is the
 * resulting state legal", which has no principal in it — the permission question
 * (may this principal write this field) is answered earlier by `runMutationGate`.
 * Threading an actor here would also mean changing every caller of
 * `validateEntityRowPatch`, several of which are platform bookkeeping with no
 * actor at all. Actor-scoped denial is a deliberate follow-up, not an oversight.
 */
const RULE_RUNNER = `
const __lobuRule = __lobuRuleModule.default;
// Value comparison, not key presence. \`patch\` carries the fully MERGED value
// set, so every metadata key is present on every metadata write — asking whether
// a key EXISTS answers "did this write touch metadata at all", which is true for
// essentially every update. Structural compare over JSON so nested objects and
// arrays behave, with undefined and null collapsed: a field absent from committed
// and written as null has not changed.
const __lobuNorm = (v) => (v === undefined ? null : v);
const __lobuDiffers = (a, b) =>
  JSON.stringify(__lobuNorm(a)) !== JSON.stringify(__lobuNorm(b));
export default async (ctx) => {
  if (typeof __lobuRule !== "function") {
    throw new Error("entity rule must export default a function");
  }
  const verdicts = [];
  for (const row of ctx.rows) {
    let verdict = { outcome: "allow" };
    const next = { ...row.committed, ...row.patch };
    const api = {
      committed: row.committed,
      patch: row.patch,
      next,
      op: ctx.op,
      changed: (f) => __lobuDiffers(row.committed[f], next[f]),
      deny: (reason) => {
        const err = new Error(String(reason));
        err.__lobuDeny = true;
        throw err;
      },
      escalate: (fields, reason) => {
        verdict = {
          outcome: "escalate",
          fields: Array.isArray(fields) ? fields : [fields],
          reason: String(reason),
        };
      },
    };
    try {
      await __lobuRule(api);
    } catch (err) {
      if (err && err.__lobuDeny) verdict = { outcome: "deny", reason: err.message };
      else throw err;
    }
    verdicts.push(verdict);
  }
  return verdicts;
};`;

/**
 * Compile an author's rule source into the artifact stored in
 * `entity_types.rules_compiled` — the exact string {@link runEntityRules}
 * later hands to `runScript`.
 *
 * The author's module is built as an IIFE bound to a global, NOT as a module,
 * and the ESM runner above is appended. That split is load-bearing: `runScript`
 * compiles its `source` itself, so the stored artifact has to survive a second
 * esbuild pass. Concatenating an already-CJS module with the runner's
 * `export default` would hand esbuild one file containing two module formats,
 * and the author's `module.exports` would resolve against the wrapper's own
 * exports rather than their module. As an IIFE the author's half is plain
 * statements, so the runner is the only module syntax in the file and the
 * second pass is unambiguous.
 *
 * Compiling at apply time (not write time) is the point of storing this at all.
 * Note `runScript` still runs the stored artifact through esbuild once per
 * distinct source per process, memoized by content hash in `run-script.ts`; what
 * apply-time compilation removes is the author's TypeScript, npm resolution and
 * bundling from the write path, not literally every esbuild call.
 */
export async function compileEntityRule(source: string): Promise<string> {
	const { compiledCode } = await compileSource(source, {
		tmpPrefix: ".entity-rule-compile-",
		label: "EntityRuleCompiler",
		buildOptions: {
			format: "iife",
			globalName: "__lobuRuleModule",
			target: "esnext",
			platform: "node",
			external: [],
		},
	});
	return `${compiledCode}\n${RULE_RUNNER}`;
}

/**
 * Evaluate one type's rule against a batch of rows.
 *
 * Returns one verdict per row, positionally. Never throws on a rule's own deny —
 * the caller decides whether a deny becomes an error (enforcing) or a log line
 * (inert), which keeps the inert-then-arm rollout a caller-side flag rather than
 * a second code path.
 *
 * A rule that crashes or times out FAILS CLOSED. It ran holding row locks and we
 * cannot distinguish a bug from a deliberate infinite loop, so the write does not
 * proceed on the strength of a rule that did not finish.
 */
export async function runEntityRules(
	batch: EntityRuleBatch,
): Promise<EntityRuleVerdict[]> {
	if (batch.rows.length === 0) return [];
	if (batch.rows.length > MAX_RULE_BATCH) {
		const out: EntityRuleVerdict[] = [];
		for (let i = 0; i < batch.rows.length; i += MAX_RULE_BATCH) {
			out.push(
				...(await runEntityRules({
					...batch,
					rows: batch.rows.slice(i, i + MAX_RULE_BATCH),
				})),
			);
		}
		return out;
	}

	// Placeholder for `sdkMode: "none"`. A rule declares no reads, so nothing
	// behind this stub is reachable from the guest.
	const noSdk = { log: () => undefined } as unknown as ClientSDK;

	const result = await runScript({
		source: batch.compiled,
		sdk: noSdk,
		context: { rows: batch.rows, op: batch.op },
		limits: { timeoutMs: batch.timeoutMs ?? RULE_BATCH_TIMEOUT_MS },
	});

	if (!result.success) {
		const detail = result.error
			? `${result.error.name}: ${result.error.message}`
			: "rule did not complete";
		return batch.rows.map(() => ({
			outcome: "deny" as const,
			reason: `rule failed: ${detail}`,
		}));
	}

	const verdicts = result.returnValue;
	if (!Array.isArray(verdicts) || verdicts.length !== batch.rows.length) {
		return batch.rows.map(() => ({
			outcome: "deny" as const,
			reason: "rule returned no usable verdict",
		}));
	}
	return verdicts as EntityRuleVerdict[];
}

/**
 * Entity row validation at the physical writer, driven by a type's compiled
 * write rules.
 *
 * These run the REAL path: an author's rule source is compiled exactly as the
 * apply path would store it, written to `entity_types.rules_compiled`, and then
 * exercised through `updateEntity` — not through the validator in isolation. A
 * rule that is never reached would pass a unit test of the evaluator and fail
 * here, which is the failure mode worth catching.
 */

import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { compileEntityRule } from "../../../authz/entity-rule-executor";
import type { Env } from "../../../index";
import type { ToolContext } from "../../../tools/registry";
import { createEntity, updateEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestAgent,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

/**
 * The invoice lifecycle as an author would write it.
 *
 * `row.patch` carries the fully MERGED metadata, not a delta, so every key shows
 * up on every write — which is exactly why `changed()` compares VALUES. Both
 * guards here lean on that: `changed("status")` is the transition test, and
 * `changed(field)` in the frozen loop is what lets an unchanged value ride along
 * in a write that touches something else. An earlier cut had `changed()` report
 * key presence instead, and every rule had to hand-roll both comparisons.
 */
const INVOICE_RULE = `
const ALLOWED = { draft: ["issued"], issued: ["posted"], posted: [] };
const FROZEN = ["issued", "posted"];
const WRITABLE_ON_EXIT = { "issued->posted": ["einvoice_uuid"] };

export default (row) => {
  if (row.op === "create") {
    if (row.next.status !== "draft") {
      row.deny("an invoice is created in draft, not " + row.next.status);
    }
    return;
  }

  const from = row.committed.status;
  const to = row.next.status;
  if (row.changed("status") && !(ALLOWED[from] || []).includes(to)) {
    row.deny("cannot move " + from + " -> " + to);
  }

  if (!FROZEN.includes(from)) return;
  const permitted = ["status"].concat(WRITABLE_ON_EXIT[from + "->" + to] || []);
  for (const field of Object.keys(row.patch)) {
    if (permitted.includes(field)) continue;
    if (!row.changed(field)) continue;
    row.deny(from + " is frozen: " + field + " is not writable");
  }
};
`;

/** A lifecycle with nothing ERP about it, to prove the seam is type-scoped. */
const TICKET_RULE = `
export default (row) => {
  if (row.op === "update" && row.committed.state === "closed" && row.next.state === "open") {
    row.deny("a closed ticket cannot be reopened");
  }
};
`;

const TEST_ENV = {} as Env;

// esbuild costs ~100ms per call, so compile each rule once for the whole file.
let invoiceCompiled: string;
let ticketCompiled: string;

function ctxFor(
	organizationId: string,
	opts: { userId?: string | null; agentId?: string | null },
): ToolContext {
	return {
		organizationId,
		userId: opts.userId ?? null,
		memberRole: "owner",
		agentId: opts.agentId ?? null,
		isAuthenticated: true,
		clientId: null,
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
		tokenType: "oauth",
		scopedToOrg: true,
		allowCrossOrg: false,
	} as unknown as ToolContext;
}

async function seedType(
	organizationId: string,
	slug: string,
	rulesCompiled: string | null,
) {
	const sql = getTestDb();
	await sql`
    INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
                              rules_compiled, created_at, updated_at)
    VALUES (${organizationId}, ${slug}, ${slug}, ${sql.json({ type: "object" })},
            ${rulesCompiled}, current_timestamp, current_timestamp)
  `;
}

async function readMetadata(id: number): Promise<Record<string, unknown>> {
	const sql = getTestDb();
	const rows = await sql<{ metadata: unknown }[]>`
    SELECT metadata FROM entities WHERE id = ${id}
  `;
	const raw = rows[0].metadata;
	return (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
		string,
		unknown
	>;
}

async function seedOrg(name: string) {
	const org = await createTestOrganization({ name });
	const user = await createTestUser();
	await addUserToOrganization(user.id, org.id, "owner");
	const agent = await createTestAgent({ organizationId: org.id });
	return { org, user, agent };
}

/**
 * Seed an invoice and walk it to `status` through legal transitions only.
 * Creates are validated now, so a fixture cannot be born mid-lifecycle — it has
 * to get there the way a tenant would.
 */
async function seedInvoice(
	status: "draft" | "issued" | "posted",
	rule: string | null = invoiceCompiled,
) {
	const { org, user, agent } = await seedOrg(`Invoice ${status}`);
	await seedType(org.id, "invoice", rule);

	const invoice = await createEntity({
		entity_type: "invoice",
		name: "INV-1",
		organization_id: org.id,
		created_by: user.id,
		metadata: { status: "draft", einvoice_uuid: null, amount: 100 },
	} as Parameters<typeof createEntity>[0]);

	const ctx = ctxFor(org.id, { userId: user.id });
	if (status === "issued" || status === "posted") {
		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			ctx,
		);
	}
	if (status === "posted") {
		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "uuid-seed" } },
			TEST_ENV,
			ctx,
		);
	}
	return { org, user, agent, invoice };
}

describe("entity row validation at the physical writer", () => {
	beforeAll(async () => {
		[invoiceCompiled, ticketCompiled] = await Promise.all([
			compileEntityRule(INVOICE_RULE),
			compileEntityRule(TICKET_RULE),
		]);
	}, 60_000);

	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("denies an AGENT editing a frozen document", async () => {
		const { org, agent, invoice } = await seedInvoice("posted");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { amount: 999 } },
				TEST_ENV,
				ctxFor(org.id, { agentId: agent.agentId }),
			),
		).rejects.toThrow(/posted is frozen: amount/);

		expect((await readMetadata(invoice.id)).amount).toBe(100);
	}, 60_000);

	it("denies a HUMAN editing a frozen document — validation has no principal in it", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		// The permission gate carves out humans. This seam answers a different
		// question ("is the resulting state legal"), so an owner is denied too.
		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { amount: 999 } },
				TEST_ENV,
				ctxFor(org.id, { userId: user.id }),
			),
		).rejects.toThrow(/posted is frozen: amount/);
	}, 60_000);

	it("denies an illegal transition and permits a legal one", async () => {
		const { org, user, invoice } = await seedInvoice("draft");
		const ctx = ctxFor(org.id, { userId: user.id });

		await expect(
			updateEntity(invoice.id, { metadata: { status: "posted" } }, TEST_ENV, ctx),
		).rejects.toThrow(/cannot move draft -> posted/);
		expect((await readMetadata(invoice.id)).status).toBe("draft");

		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			ctx,
		);
		expect((await readMetadata(invoice.id)).status).toBe("issued");
	}, 60_000);

	it("permits a writableOnExit field in the same write as its move", async () => {
		const { org, user, invoice } = await seedInvoice("issued");

		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "uuid-xyz" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("posted");
		expect(after.einvoice_uuid).toBe("uuid-xyz");
	}, 60_000);

	it("denies renaming a frozen document", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		// Freezing a document has to stop a rename, not merely a metadata edit —
		// which is why `$name` is a governed column rather than an ungoverned one.
		await expect(
			updateEntity(invoice.id, { name: "INV-RENAMED" }, TEST_ENV, ctxFor(org.id, {
				userId: user.id,
			})),
		).rejects.toThrow(/posted is frozen: \$name/);
	}, 60_000);

	it("permits an idempotent rewrite of an unchanged value while frozen", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		// The merged patch carries every metadata key on every write, so a rule
		// that denied on presence rather than on change would reject this.
		await updateEntity(
			invoice.id,
			{ metadata: { amount: 100 } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		expect((await readMetadata(invoice.id)).amount).toBe(100);
	}, 60_000);

	it("leaves a type declaring no rules untouched", async () => {
		const { org, user, invoice } = await seedInvoice("draft", null);

		// No rule means no isolate — the write that the invoice rule would have
		// rejected outright goes straight through.
		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		expect((await readMetadata(invoice.id)).status).toBe("posted");
	}, 60_000);

	it("ignores a write that leaves the governed field untouched", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		// Regression for a real defect: `changed()` reported key presence, so this
		// write — which does not touch `status` at all — was denied by the
		// transition guard. A unit test missed it because its fixtures were
		// delta-shaped; only the seam produces the merged shape that exposes it.
		await updateEntity(
			invoice.id,
			{ metadata: { einvoice_uuid: "uuid-seed" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		expect((await readMetadata(invoice.id)).status).toBe("posted");
	}, 60_000);

	it("scopes rules to their own type", async () => {
		const { org, user } = await seedOrg("Mixed types");
		await seedType(org.id, "invoice", invoiceCompiled);
		await seedType(org.id, "ticket", ticketCompiled);
		const ctx = ctxFor(org.id, { userId: user.id });

		const ticket = await createEntity({
			entity_type: "ticket",
			name: "TCK-1",
			organization_id: org.id,
			created_by: user.id,
			metadata: { state: "open" },
		} as Parameters<typeof createEntity>[0]);

		// The invoice rule would have denied a create whose status is not "draft".
		// The ticket has no `status` at all and its own rule permits the create.
		await updateEntity(ticket.id, { metadata: { state: "closed" } }, TEST_ENV, ctx);
		expect((await readMetadata(ticket.id)).state).toBe("closed");

		await expect(
			updateEntity(ticket.id, { metadata: { state: "open" } }, TEST_ENV, ctx),
		).rejects.toThrow(/closed ticket cannot be reopened/);
	}, 60_000);
});

