      action: 'update',
      entity_id: entityId,
      metadata,
      ...(opts?.affirm_fields ? { affirm_fields: opts.affirm_fields } : {}),
      ...(opts?.automation_source ? { automation_source: opts.automation_source } : {}),
    },
