  ) as Promise<{
    action: 'update';
    applied_fields?: string[];
    blocked_fields?: string[];
    approval_queued?: boolean;
    approval_url?: string;
    approval_run_id?: number;
    approval_fields?: Record<string, unknown>;
    approval_current?: Record<string, unknown>;
    approval_attribution?: 'agent' | 'automation';
  }>;
}

