/**
 * Would the write the caller ACTUALLY proposed be legal?
 *
 * A hold can split a legal write into an illegal fragment, and rescuing that is
 * the whole point of deferring. But the rescue only makes sense if the full
 * proposal stands on its own: a card built from a proposal the rule rejects
 * anyway could never be applied, because approving replays it and the rule
 * denies it again — an approval request nobody can satisfy.
 *
 * An `escalate` counts as legal here: the rule asking for review IS the card.
 * A rule that crashes or times out does not, so a broken rule surfaces as an
 * error instead of an unanswerable approval.
 */
async function fullProposalIsLegal(params: {
	tx: DbClient;
	entityId: number;
	patch: EntityRowPatch;
}): Promise<boolean> {
	try {
		await validateEntityRowPatch({
			tx: params.tx,
			ids: [params.entityId],
			patch: params.patch,
		});
		return true;
	} catch (err) {
		return (
			err instanceof EntityRowValidationError &&
			err.verdict.outcome === "escalate"
		);
	}
}

