import type { EntityWriteRule } from "@lobu/cli/config";

const ALLOWED: Record<string, string[]> = {
  draft: ["issued"],
  issued: ["posted"],
  posted: [],
};

const rule: EntityWriteRule = (row) => {
  if (row.op === "create") {
    if (row.next.status !== "draft") {
      row.deny("an invoice is created in draft, not " + row.next.status);
    }
    return;
  }
  const from = row.committed.status as string;
  const to = row.next.status as string;
  if (row.changed("status") && !(ALLOWED[from] || []).includes(to)) {
    row.deny("cannot move " + from + " -> " + to);
  }
};

export default rule;
