1	/**
2	 * Approval interceptor — the ACL plugin for the entity mutation gate.
3	 *
4	 * This is the ONLY module that knows the approval-policy layer exists: it wraps
5	 * the `entity-policy` decisions and builds durable approval proposals via
6	 * `entity-field-approval`. It exports plain values (`approvalInterceptor` + the
7	 * two deferral builders); the gate statically imports them into its builtin
8	 * registry, so the interceptor ships in every execution path — server, worker,
9	 * tests, and the production esbuild bundle alike.
10	 *
11	 * It imports the gate ONLY for types (erased at compile time), so there is no
12	 * runtime edge back into the gate at module init — the runtime cycle
13	 * (gate → this → entity-field-approval → entity-management → gate) touches the
14	 * gate's hoisted function exports at call time only.
15	 *
16	 * Adding a second cross-cutting gate (quota, rate limit, …) is a NEW sibling
17	 * file exporting its own `MutationInterceptor`, appended to the gate's
18	 * `BUILTIN_INTERCEPTORS` — core mutation code never changes.
19	 */
20	
21	import {
22		proposeEntityCreate,
23		proposeEntityDelete,
24		proposeEntityFieldChange,
25	} from "../tools/admin/entity-field-approval";
26	import type { EntityData } from "../utils/entity-management";
27	import type {
28		DeferredMutation,
29		EntityMutationRequest,
30		MutationAttribution,
31		MutationInterceptor,
32		UpdateDecision,
33	} from "./entity-mutation-gate";
34	import {
35		evaluateEntityFieldUpdates,
36		evaluateEntityMutation,
37	} from "./entity-policy";
38	
39	function reasonFor(
40		attribution: MutationAttribution,
41		verb: "creating" | "deleting",
42		entityTypeSlug: string,
43		name: string | undefined,
44	): string {
45		const actor = attribution === "automation" ? "An Automation" : "An agent";
46		const label = name ? `${entityTypeSlug} "${name}"` : entityTypeSlug;
47		return `${actor} proposes ${verb} ${label}.`;
48	}
49	
50	function fieldChangeReason(
51		attribution: MutationAttribution,
52		fields: string[],
53	): string {
54		const actor = attribution === "automation" ? "An Automation" : "An agent";
55		return `${actor} proposes updating ${fields.join(", ")} on this entity.`;
56	}
57	
58	export function buildCreateDeferral(args: {
59		entityData: EntityData;
60		proposal: Record<string, unknown>;
61		attribution: MutationAttribution;
62		/**
63		 * Overrides the generated "an agent proposes creating x" line. Set when a
64		 * WRITE RULE caused the hold, so the approver reads the rule's own words
65		 * instead of a sentence that does not say why this create needs a human.
66		 */
67		reason?: string;
68		/** Fields the rule escalated — what the approver is consenting to. */
69		escalatedFields?: string[];
70		automationId?: number | null;
71		windowId?: number | null;
72	}): DeferredMutation {
73		const name =
74			typeof args.entityData.name === "string" ? args.entityData.name : undefined;
75		return {
76			display: {
77				action: "create",
78				attribution: args.attribution,
79				proposal: args.proposal,
80			},
81			queue: (ctx) =>
82				proposeEntityCreate(ctx, {
83					entity_data: args.entityData,
84					proposal: args.proposal,
85					escalated_fields: args.escalatedFields,
86					automation_id: args.automationId ?? null,
87					window_id: args.windowId ?? null,
88					attribution: args.attribution,
89					reason:
90						args.reason ??
91						reasonFor(
92							args.attribution,
93							"creating",
94							args.entityData.entity_type,
95							name,
96						),
97				}),
98		};
99	}
100	
101	export function buildFieldChangeDeferral(args: {
102		entityId: number;
103		fields: Record<string, unknown>;
104		current: Record<string, unknown>;
105		attribution: MutationAttribution;
106		/**
107		 * Overrides the generated "agent wants to change x, y" line. Set when a
108		 * WRITE RULE caused the hold, so the approver reads the rule's own words
109		 * instead of a field list that does not explain itself.
110		 */
111		reason?: string;
112		/** Fields the rule escalated — what the approver is consenting to. */
113		escalatedFields?: string[];
114		automationId?: number | null;
115		windowId?: number | null;
116	}): DeferredMutation {
117		return {
118			display: {
119				action: "update",
120				attribution: args.attribution,
121				fields: args.fields,
122				current: args.current,
123			},
124			queue: (ctx) =>
125				proposeEntityFieldChange(ctx, {
126					entity_id: args.entityId,
127					fields: args.fields,
128					current: args.current,
129					automation_id: args.automationId ?? null,
130					window_id: args.windowId ?? null,
131					attribution: args.attribution,
132					reason:
133						args.reason ??
134						fieldChangeReason(args.attribution, Object.keys(args.fields)),
135				}),
136		};
137	}
138	
139	async function evaluate(
140		req: EntityMutationRequest,
141	): Promise<
142		| { outcome: "allow" }
143		| { outcome: "deny"; reason: string }
144		| { outcome: "defer"; deferred: DeferredMutation }
145		| UpdateDecision
146		| null
147	> {
148		// An automation acting under its owning agent folds the AGENT'S rows in too, so
149		// the agent envelope binds while a pre-existing automation-specific restriction
150		// can only tighten (the agent envelope never loosens it away).
151		const ownerAgentId = req.ownerAgentId ?? null;
152		// An automation whose owning agent couldn't be resolved fails closed downstream.
153		const ownerResolved = req.ownerResolved ?? true;
154	
155		if (req.action === "update") {
156			const decisions = await evaluateEntityFieldUpdates({
157				organizationId: req.organizationId,
158				principalKind: req.principalKind,
159				principalId: req.principalId ?? null,
160				ownerAgentId,
161				ownerResolved,
162				entityTypeSlug: req.entityTypeSlug,
163				entityId: req.entityId,
164				entityOrgId: req.entityOrgId ?? null,
165				fields: req.fields,
166				sql: req.sql,
167			});
168			const requireApproval = new Set<string>();
169			for (const [field, decision] of Object.entries(decisions)) {
170				if (decision === "deny") {
171					return {
172						outcome: "deny",
173						reason: `Policy denied update to field '${field}'`,
174					};
175				}
176				if (decision === "require_approval") requireApproval.add(field);
177			}
178			return { outcome: "fields", requireApproval };
179		}
180	
181		const decision = await evaluateEntityMutation({
182			organizationId: req.organizationId,
183			principalKind: req.principalKind,
184			principalId: req.principalId ?? null,
185			ownerAgentId,
186			ownerResolved,
187			action: req.action,
188			entityTypeSlug: req.entityTypeSlug,
189			entityId: req.action === "delete" ? req.entityId : undefined,
190			entityOrgId: req.action === "delete" ? req.entityOrgId : undefined,
191			sql: req.sql,
192		});
193	
194		if (decision === "deny") {
195			return {
196				outcome: "deny",
197				reason:
198					req.action === "create"
199						? `Policy denied creating ${req.entityTypeSlug}`
200						: `Policy denied deleting entity ${req.entityId}`,
201			};
202		}
203		if (decision === "allow") return { outcome: "allow" };
204	
205		// require_approval → defer with a POST-COMMIT queue() closure.
206		if (req.action === "create") {
207			return {
208				outcome: "defer",
209				deferred: buildCreateDeferral({
210					entityData: req.entityData,
211					proposal: req.proposal,
212					attribution: req.attribution,
213					automationId: req.automationId,
214					windowId: req.windowId,
215				}),
216			};
217		}
218		const name =
219			typeof req.current.name === "string" ? req.current.name : undefined;
220		return {
221			outcome: "defer",
222			deferred: {
223				display: {
224					action: "delete",
225					attribution: req.attribution,
226					current: req.current,
227					proposal: {
228						entity_id: req.entityId,
229						entity_type: req.entityTypeSlug,
230						name,
231						force_delete_tree: req.forceDeleteTree ?? false,
