1	/**
2	 * Creates reach the validation seam.
3	 *
4	 * This file began as a spike proving the opposite. `insertEntityRow` never
5	 * called the validator, so every state rule was trivially routable: an agent
6	 * denied a `draft -> posted` update simply created the document already posted,
7	 * and "posting requires an e-invoice UUID" only ever bit someone who took a
8	 * legal draft and edited it — i.e. someone already following the rules.
9	 *
10	 * The fix was the same brand the update path already carried, applied to the
11	 * second writer, so a caller that forgets to validate a create fails to compile.
12	 * The cases below are the regression test for that: the first asserts the create
13	 * is now DENIED, and the second is the contrast that pins the rule as the cause
14	 * rather than some unrelated error.
15	 */
16	
17	import { beforeAll, beforeEach, describe, expect, it } from "vitest";
18	import { compileEntityRule } from "../../../authz/entity-rule-executor";
19	import type { Env } from "../../../index";
20	import type { AuthContext } from "../../../tools/execute";
21	import { executeTool } from "../../../tools/execute";
22	import { applyEntityChangeProposal } from "../../../tools/admin/entity-field-approval";
23	import type { ToolContext } from "../../../tools/registry";
24	import { createEntity, updateEntity } from "../../../utils/entity-management";
25	import { initWorkspaceProvider } from "../../../workspace";
26	import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
27	import {
28		addUserToOrganization,
29		createTestAgent,
30		createTestOrganization,
31		createTestUser,
32	} from "../../setup/test-fixtures";
33	
34	/**
35	 * `posted` is terminal and frozen. Reaching it legally means passing through
36	 * `issued`, and `einvoice_uuid` is only writable on the exit INTO `posted`.
37	 *
38	 * The `op === "create"` branch is the whole point: a create is an update from
39	 * nothing, so `committed` is empty and the rule decides what a row is allowed to
40	 * be born as. Without that branch the transition table below governs edits only.
41	 */
42	const INVOICE_RULE = `
43	const ALLOWED = { draft: ["issued"], issued: ["posted"], posted: [] };
44	
45	export default (row) => {
46	  if (row.op === "create") {
47	    if (row.next.status !== "draft") {
48	      row.deny("an invoice is created in draft, not " + row.next.status);
49	    }
50	    return;
51	  }
52	  const from = row.committed.status;
53	  const to = row.next.status;
54	  if (from !== to && !(ALLOWED[from] || []).includes(to)) {
55	    row.deny("cannot move " + from + " -> " + to);
56	  }
57	  if (to === "posted" && !row.next.einvoice_uuid) {
58	    row.deny("posting requires an e-invoice UUID");
59	  }
60	};
61	`;
62	
63	/**
64	 * A rule that holds a CREATE for review rather than rejecting it. The row does
65	 * not exist yet, so there is nothing to hold fields against — the whole
66	 * proposed row is either created or it is not.
67	 */
68	const BIG_INVOICE_RULE = `
69	export default (row) => {
70	  if (row.op === "create" && row.next.amount > 50000) {
71	    row.escalate(["amount"], "a new invoice over 50k needs sign-off");
72	  }
73	};
74	`;
75	
76	const TEST_ENV = {} as Env;
77	
78	/** `executeTool` goes through the real access-controlled path, so it needs a real env. */
79	const TOOL_ENV: Env = {
80		ENVIRONMENT: "test",
81		DATABASE_URL: process.env.DATABASE_URL,
82		JWT_SECRET: "test-jwt-secret-for-testing-only",
83		BETTER_AUTH_SECRET: "test-auth-secret-for-testing-only",
84	} as Env;
85	
86	let invoiceCompiled: string;
87	let bigInvoiceCompiled: string;
88	
89	function ctxFor(
90		organizationId: string,
91		opts: { userId?: string | null; agentId?: string | null },
92	): ToolContext {
93		return {
94			organizationId,
95			userId: opts.userId ?? null,
96			memberRole: "owner",
97			agentId: opts.agentId ?? null,
98			isAuthenticated: true,
