111		await addUserToOrganization(user.id, org.id, "owner");
112		const agent = await createTestAgent({ organizationId: org.id });
113		await sql`
114	    INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
115	                              rules_compiled, created_at, updated_at)
