117	            ${rules}, current_timestamp, current_timestamp)
118	  `;
119		return { org, user, agent };
120	}
121	
122	/** Agent auth context — an agent run, so a hold routes to a human. */
123	function agentAuthCtx(orgId: string, userId: string, agentId: string): AuthContext {
124		return {
125			organizationId: orgId,
126			tokenOrganizationId: orgId,
127			userId,
128			memberRole: "owner",
129			agentId,
130			requestedAgentId: agentId,
131			isAuthenticated: true,
132			clientId: null,
133			scopes: ["mcp:read", "mcp:write", "mcp:admin"],
134			tokenType: "oauth",
135			requestUrl: `http://localhost/api/${orgId}`,
136			baseUrl: "",
137			scopedToOrg: true,
138			allowCrossOrg: false,
139		};
140	}
141	
142	async function statusOf(id: number): Promise<unknown> {
143		const sql = getTestDb();
144		const rows = await sql<{ metadata: unknown }[]>`
145	    SELECT metadata FROM entities WHERE id = ${id}`;
146		const raw = rows[0].metadata;
147		const md = (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
148			string,
149			unknown
150		>;
151		return md.status;
152	}
153	
154	async function countInvoices(organizationId: string): Promise<number> {
155		const sql = getTestDb();
156		const rows = await sql<{ n: string }[]>`
157	    SELECT count(*)::text AS n FROM entities WHERE organization_id = ${organizationId}
158	  `;
159		return Number(rows[0].n);
160	}
161	
162	describe("creates reach the validation seam", () => {
163		beforeAll(async () => {
164			// `queue()` builds an approval URL, which needs the workspace provider.
165			await initWorkspaceProvider();
166			[invoiceCompiled, bigInvoiceCompiled] = await Promise.all([
167				compileEntityRule(INVOICE_RULE),
168				compileEntityRule(BIG_INVOICE_RULE),
169			]);
170		}, 60_000);
171	
172		beforeEach(async () => {
173			await cleanupTestDatabase();
174		});
175	
176		it("denies an invoice born DIRECTLY in the terminal frozen state", async () => {
177			const { org, user } = await seedOrg();
178	
179			await expect(
180				createEntity({
181					entity_type: "invoice",
182					name: "INV-BORN-POSTED",
183					organization_id: org.id,
184					created_by: user.id,
185					metadata: { status: "posted", einvoice_uuid: "uuid-1" },
186				} as Parameters<typeof createEntity>[0]),
187			).rejects.toThrow(/an invoice is created in draft, not posted/);
188	
189			// The whole insert rolled back — no half-created row behind the denial.
190			expect(await countInvoices(org.id)).toBe(0);
191		}, 60_000);
