202			} as Parameters<typeof createEntity>[0]);
203			expect(await statusOf(invoice.id)).toBe("draft");
204	
205			await expect(
206				updateEntity(
207					invoice.id,
208					{ metadata: { status: "posted", einvoice_uuid: "uuid-1" } },
